[1983] = "你隊伍的隊長的",
-- fad43537 English: Absolute health target (negative means deficit) or percentage fraction.
[1984] = "絕對生命力目標（負數表示損失量）或百分比小數。",
-- 29a55788 English: All original results, preserving nil positions and return count.
[1985] = "所有原始結果，保留 nil 的位置與傳回值數量。",
-- c7e69e75 English: Apply the legacy integer or canonical numeric-string spelling test. Numbers use
--     floor equality; strings must equal the spelling obtained after numeric conversion and floor.
--     Other types return false. This is not a finite-number validator.
[1986] = "執行舊版的整數或標準數字字串拼寫測試。數字使用無條件捨去後的相等比較；字串必須等於經數字轉換並無條件捨去後得到的拼寫。其他型別傳回 false。這不是有限數字的驗證器。",
-- 69eb2e21 English: Arguments forwarded unchanged to the observed function.
[1987] = "原樣轉送給被觀測函式的參數。",
-- 1d513028 English: Arguments forwarded unchanged; types, identity, arity and nil positions
--     distinguish cache entries.
[1988] = "原樣轉送的參數；型別、身分、參數數量與 nil 位置用於區分快取項目。",
-- 3e8d2702 English: Availability or query-validation reason for a nil level observation.
[1989] = "等級觀測為 nil 時的可用性或查詢驗證原因。",
-- e2ffe9af English: Availability or query-validation reason for a nil level.
[1990] = "等級為 nil 時的可用性或查詢驗證原因。",
-- 66134514 English: Availability or query-validation reason when no current state can be read.
[1991] = "無法讀取目前狀態時的可用性或查詢驗證原因。",
-- 77b92c6d English: Availability or query-validation reason when the whole observation is
--     unavailable.
[1992] = "整個觀測無法使用時的可用性或查詢驗證原因。",
-- 11483c22 English: Availability or validation reason for a nil result.
[1993] = "結果為 nil 時的可用性或驗證原因。",
-- bd62d347 English: Availability or validation reason when the record is nil.
[1994] = "記錄為 nil 時的可用性或驗證原因。",
-- cab01ca9 English: Availability or validation reason when the result is nil.
[1995] = "結果為 nil 時的可用性或驗證原因。",
-- 37cddc45 English: Availability reason for a nil result.
[1996] = "結果為 nil 時的可用性原因。",
-- eced4849 English: Availability reason when resolution fails; nil on success.
[1997] = "解析失敗時的可用性原因；成功時為 nil。",
-- 09403547 English: Cache an observation after it returns a non-nil value; retry observations whose
--     entire return tuple is nil. Uses the same exact argument keys as getCached.
[1998] = "在觀測傳回非 nil 值後將其快取；對整個傳回元組都為 nil 的觀測會重試。使用與 getCached 完全相同的參數鍵。",
-- ec80f70e English: Calculate a checked health-history rate using an explicit finite window and
--     clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array
--     holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows
--     and accumulation bins across both streams; excess or invalid consumed arithmetic returns
--     unavailable, never a partial estimate or clamp. This new API has its own source identity;
--     historical trend functions remain unchanged.
[1999] = "使用明確的有限時間區間與時鐘，計算經過檢查的生命力歷史速率。保留有序加權、逐列即時標準捨入、被略過的資料流、陣列空洞、小數鍵以及最終存取時的時長。固定的 4096 單位預算涵蓋兩個資料流中被存取的列與累加區間；超出預算或無效的已消耗運算會傳回無法使用，絕不傳回部分估算或截斷值。這個新 API 有其自己的原始碼身分；歷史趨勢函式保持不變。",
-- e3a904cc English: Call an observation once per cache and exact argument tuple, including nil
--     results. Pass the evaluation cache to share observations within a recommendation cycle; nil
--     cache calls directly.
[2000] = "對每個快取與完全相同的參數元組只呼叫一次觀測，包括 nil 結果。傳入評估快取可在一個建議週期內共用觀測；快取為 nil 時直接呼叫。",
-- cb8a709c English: Callback invoked after changing the selected unit.
[2001] = "變更所選單位後呼叫的回呼。",
-- f4755bc2 English: Callback receiving the committed spell value.
[2002] = "接收已提交法術值的回呼。",
-- 8473e032 English: Caller-owned evaluation observation cache; nil queries afresh.
[2003] = "由呼叫端擁有的評估觀測快取；為 nil 時重新查詢。",
-- d07ec966 English: Capability or clock observation availability reason.
[2004] = "功能或時鐘觀測的可用性原因。",
-- aca2f51b English: Capability or observation availability reason for a nil class.
[2005] = "職業為 nil 時的功能或觀測可用性原因。",
-- fb8dd5ac English: Check whether a spell can be recommended now, allowing a spell whose remaining
--     cooldown ends with the current global cooldown. On Retail and Forever, where cooldown times
--     are secret in combat, readiness comes from the never-secret isEnabled, isActive and isOnGCD
--     flags instead. This checks cooldown readiness only; it does not check learned status, range
--     or resource usability. Pass evaluation time from evalStart or GetTime().
[2006] = "檢查某個法術現在能否被建議，允許剩餘冷卻時間隨目前共用冷卻一同結束的法術。在正式版與永久中，戰鬥中的冷卻時間是機密值，因此改為依據永不為機密的 isEnabled、isActive 與 isOnGCD 旗標判斷是否就緒。此函式只檢查冷卻是否就緒；不檢查是否已學會、距離或資源是否足夠。請傳入來自 evalStart 或 GetTime() 的評估時間。",
-- 1081f5fc English: Check whether a table has a non-nil value at a key. A stored false value still
--     counts as present; this does not scan table values.
[2007] = "檢查表格中某個鍵是否有非 nil 的值。儲存的 false 值仍算作存在；這不會掃描表格中的值。",
-- 3f1a5911 English: Checkbox widget with boolean value and callback methods.
[2008] = "帶有布林值與回呼方法的核取方塊元件。",
-- 8373609b English: Choose the supplied player value only for the literal player unit token; every
--     other unit selects the nonplayer value. Selected false and nil values are preserved.
[2009] = "僅當單位代碼為字面上的 player 時才選擇所提供的玩家值；其他所有單位都會選擇非玩家值。選中的 false 與 nil 值會被保留。",
-- 68e9defe English: Classification, validation or availability reason for a nil result.
[2010] = "結果為 nil 時的分類、驗證或可用性原因。",
-- 7fc7159a English: Classify a numeric item as a glyph for the requested class, using guarded
--     native item metadata. Class is optional and defaults to the readable player class. This
--     establishes item classification only, not equipped status or an item-to-glyph-spell ID
--     mapping.
[2011] = "使用受保護的原生物品中繼資料，將一個數字物品歸類為所請求職業的雕紋。職業是選擇性的，預設為可讀取的玩家職業。這只確定物品分類，不確定裝備狀態，也不提供物品到雕紋法術 ID 的對應。",
-- 355b4c25 English: Client-family, query-validation or required-observation availability reason for
--     a nil result.
[2012] = "結果為 nil 時的用戶端系列、查詢驗證或所需觀測的可用性原因。",
-- 56d0a810 English: Client-policy, capability, call or observation availability reason for a nil
--     form.
[2013] = "形態為 nil 時的用戶端政策、功能、呼叫或觀測可用性原因。",
-- fffddfca English: Client-policy, capability, call or observation availability reason for a nil
--     record.
[2014] = "記錄為 nil 時的用戶端政策、功能、呼叫或觀測可用性原因。",
-- 7a0f627b English: Client-policy, native-call or required membership availability reason for a nil
--     record.
[2015] = "記錄為 nil 時的用戶端政策、原生呼叫或所需成員身分的可用性原因。",
-- 0a8d99a6 English: Closed kind: runner, resist or immune.
[2016] = "封閉的種類：runner、resist 或 immune。",
-- 6999f76c English: Closed scalar kind: current or maximum.
[2017] = "封閉的純量種類：current 或 maximum。",
-- a7224c57 English: Collect table keys and sort them by their associated values using Lua less-than
--     comparison. This sorts values rather than key names; equal values have no guaranteed key
--     order.
[2018] = "收集表格的鍵，並使用 Lua 的小於比較依其對應的值排序。這是依值排序而不是依鍵名排序；值相等時鍵的順序不確定。",
-- 508c105b English: Combat-policy, capability, observation or scan-budget reason for a nil count.
[2019] = "計數為 nil 時的戰鬥政策、功能、觀測或掃描預算原因。",
-- 14b9d8a2 English: Combined signed weighted rate from the original formula; malformed or nonfinite
--     inputs retain the legacy error/numeric behavior.
[2020] = "來自原始公式的帶正負號加權合併速率；格式錯誤或非有限的輸入保留舊版的錯誤/數值行為。",
-- ee842735 English: Compare the selected unit creature ID with one existing saved creature-type
--     key. Resolve the fixed key-to-ID identity in one private executable mapper; gameplay matching
--     does not depend on the mutable localized UI caption map. Share complete native observations
--     within the supplied evaluation-pass cache by actual observer, receiver and unit, including
--     absence and unavailable reasons. Known absence or a known different ID returns false; an
--     unavailable required observation returns nil with a reason. No longterm state or caption
--     mutation is added.
[2021] = "將所選單位的生物 ID 與一個現有的已儲存生物類型鍵進行比較。在一個私有的可執行對應器中解析固定的鍵到 ID 的對應；遊戲中的比對不依賴可變的在地化介面標題對應。在所提供的評估輪次快取中，依實際的觀測者、接收者與單位共用完整的原生觀測，包括不存在與無法使用的原因。已知不存在或已知 ID 不同時傳回 false；所需觀測無法使用時傳回 nil 及原因。不會新增長期狀態或修改標題。",
-- 098e89f6 English: Compare two exact unit tokens using UnitIsUnit after checking only the first
--     token with UnitExists. A readable absent first unit returns false without comparing. Required
--     missing, failed, restricted or malformed observations return nil with a reason. No second
--     existence query, GUID lookup or inferred identity is added.
[2022] = "只用 UnitExists 檢查第一個單位代碼後，使用 UnitIsUnit 比較兩個確切的單位代碼。若第一個單位可讀且不存在，則不進行比較直接傳回 false。所需的觀測缺少、失敗、受限或格式錯誤時傳回 nil 及原因。不會額外進行第二次存在性查詢、GUID 查詢或推斷身分。",
-- f92fafbd English: Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS,
--     GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and
--     return nil; operands must support the selected Lua operation.
[2023] = "使用 RM 運算子識別碼比較兩個值：LESSTHAN、LESSTHANOREQUALS、GREATERTHAN、GREATERTHANOREQUALS、EQUALS、NOTEQUALS 或 DIVISIBLE。無效的運算子會發出警告並傳回 nil；運算元必須支援所選的 Lua 運算。",
-- 4d1da429 English: Comparison operator key, such as EQUALS or LESSTHAN.
[2024] = "比較運算子鍵，例如 EQUALS 或 LESSTHAN。",
-- 8d6dc0da English: Comparison result, or nil for an unknown operator.
[2025] = "比較結果；運算子未知時為 nil。",
-- 45e7a5a6 English: Comparison text retaining named Boolean alternative markup.
[2026] = "保留命名布林備選標記的比較文字。",
-- beb1fd9a English: Complete matching class count, including zero, or nil when unavailable.
[2027] = "符合職業的完整計數（包括零）；無法使用時為 nil。",
-- 3abb0dce English: Complete nonnegative observed count including zero, or nil when unavailable.
[2028] = "完整的非負觀測計數（包括零）；無法使用時為 nil。",
-- a3cbc46a English: Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and
--     DoLayout.
[2029] = "支援 SetLayout、AddChild、SetUserData、SetWidth 與 DoLayout 的條件容器。",
-- 1edda05a English: Condition value record containing spell, ranked and disabled fields; updated in
--     place.
[2030] = "包含 spell、ranked 與 disabled 欄位的條件值記錄；會被原地更新。",
-- bd948209 English: Condition value record updated when a unit is chosen.
[2031] = "選擇單位時會被更新的條件值記錄。",
-- 49082497 English: Configured unit selector; add it with parent:AddChild(widget).
[2032] = "已設定的單位選擇器；使用 parent:AddChild(widget) 新增它。",
-- 93e87554 English: Copy a table using tostring of each original key as the destination key. Values
--     retain their original identities. Colliding stringified keys overwrite each other in
--     unspecified pairs traversal order.
[2033] = "複製一個表格，以每個原始鍵的 tostring 結果作為目標鍵。值保留其原始身分。字串化後相互衝突的鍵會依未指定的 pairs 走訪順序相互覆蓋。",
-- dcd01801 English: Count all entries visited by pairs, including false values and sparse numeric
--     or nonnumeric keys. A nil table has length zero.
[2034] = "統計 pairs 走訪到的所有項目，包括 false 值以及稀疏的數字鍵或非數字鍵。nil 表格的長度為零。",
-- 7ee6eac7 English: Count matching class tokens in the current fixed roster. Read group membership
--     first; when requested, raid membership selects raid1 through raid40 without a separate player
--     fact. Solo and party paths read player first, then party1 through party4 when grouped. A
--     complete known roster returns a count, including zero; any required unavailable fact returns
--     nil with a reason. Complete observations share the evaluation-pass cache; no player class
--     persists across passes. Archived raw callbacks retain their original load-time class
--     separately.
[2035] = "統計目前固定名單中符合的職業代碼。先讀取隊伍成員身分；在要求時，團隊成員身分會選擇 raid1 到 raid40，而不另外讀取玩家資訊。單人與隊伍路徑會先讀取 player，組隊時再讀取 party1 到 party4。完整且已知的名單會傳回計數（包括零）；任何所需資訊無法使用時傳回 nil 及原因。完整的觀測共用評估輪次快取；玩家職業不會跨輪次保留。已封存的原始回呼會另外保留其原有的載入時職業。",
-- ddfd3a7c English: Count only GUID-keyed units already in the observed membership snapshot. Verify
--     current token identity before using the published threat observer; known absent or reused
--     tokens are excluded without adding replacements. Complete identity and threat observations
--     share only the supplied evaluation cache, while membership is traversed fresh. Known nonenemy
--     or optional nil threat is not counted; required unreadable, malformed or failed facts make
--     the entire result unavailable. This does not enumerate a complete roster, apply a range
--     filter or modify tracked records.
[2036] = "只統計已在觀測成員快照中、以 GUID 為鍵的單位。在使用已發布的威脅值觀測器之前，會先驗證目前代碼的身分；已知不存在或被重複使用的代碼會被排除，且不會新增替代者。完整的身分與威脅值觀測只共用所提供的評估快取，而成員身分會重新走訪。已知的非敵人或選擇性的 nil 威脅值不計入；所需資訊無法讀取、格式錯誤或失敗時，整個結果為無法使用。這不會列舉完整的名單、套用距離篩選或修改被追蹤的記錄。",
-- 02e149c6 English: Create a condition field container with RM-owned List, Table and responsive
--     spell-field layouts. It accepts registered native condition widgets; add children with
--     AddChild and attach the group to the callback parent.
[2037] = "建立一個條件欄位容器，使用 RM 自有的 List、Table 與自適應法術欄位版面。它接受已註冊的原生條件元件；使用 AddChild 新增子項目，並將該群組附加到回呼的父層。",
-- 24b26357 English: Create a configured unit selector bound to a condition value record. Returns
--     the widget for the caller to add to the condition callback parent.
[2038] = "建立一個綁定到條件值記錄的已設定單位選擇器。傳回該元件，由呼叫端將其新增到條件回呼的父層。",
-- 704feebd English: Create a native boolean condition control. Configure SetLabel, SetValue,
--     SetDisabled and OnValueChanged; add it with parent:AddChild(widget).
[2039] = "建立一個原生的布林條件控制項。設定 SetLabel、SetValue、SetDisabled 與 OnValueChanged；使用 parent:AddChild(widget) 新增它。",
-- d67fc3b8 English: Create a native button using the shared condition widget lifecycle and
--     workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction;
--     OnClick receives the mouse button. Add it to the callback parent with
--     parent:AddChild(widget).
[2040] = "使用共用的條件元件生命週期與工作台主題建立一個原生按鈕。SetText、SetDisabled 與 SetCallback 用於設定其標籤與互動；OnClick 會收到所按的滑鼠按鍵。將其使用 parent:AddChild(widget) 新增到回呼的父層。",
-- d4341110 English: Create a native condition selector. SetList accepts key-to-label or
--     key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with
--     parent:AddChild(widget).
[2041] = "建立一個原生的條件選擇器。SetList 接受鍵到標籤或鍵到項目的對應；SetValue 選擇一個鍵，OnValueChanged 回報變化。使用 parent:AddChild(widget) 新增它。",
-- e149229e English: Create a native image control using the condition widget lifecycle. SetImage
--     and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and
--     OnLeave use the shared callback contract. Add the control to the callback parent with
--     parent:AddChild(widget).
[2042] = "使用條件元件生命週期建立一個原生圖像控制項。SetImage 與 SetImageSize 用於選擇材質；SetText 可選擇性地新增說明文字。OnClick、OnEnter 與 OnLeave 使用共用的回呼約定。將該控制項使用 parent:AddChild(widget) 新增到回呼的父層。",
-- b943d164 English: Create a native numeric condition input with a slider and typed numeric field.
--     Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports
--     committed values. Add it with parent:AddChild(widget).
[2043] = "建立一個帶有滑桿與數字輸入框的原生數值條件輸入控制項。設定 SetSliderValues、SetValue、SetIsPercent 與 SetCallback；OnValueChanged 回報已提交的值。使用 parent:AddChild(widget) 新增它。",
-- a67c621c English: Create a native position pad using the shared directional controls.
--     OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and
--     the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the
--     callback parent with parent:AddChild(widget).
[2044] = "使用共用的方向控制項建立一個原生位置面板。OnOffsetChanged 回報水平與垂直方向、是否按下了「置中」，以及增量（一，或按住 Shift 時為十）。SetDisabled 控制互動；將該面板使用 parent:AddChild(widget) 新增到回呼的父層。",
-- 25defe9e English: Create a native text input using the condition widget contract. SetLabel,
--     SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the
--     callback parent with parent:AddChild(widget).
[2045] = "使用條件元件約定建立一個原生文字輸入框。SetLabel、SetText、SetDisabled 與 SetCallback 用於設定它；OnEnterPressed 提交文字。使用 parent:AddChild(widget) 將其新增到回呼的父層。",
-- edff3bd0 English: Create a shallow filtered copy despite the historical deepcopy name. Nested
--     values retain their original identities and the source metatable is not copied. By default
--     exclude keys listed among except values; invert true includes only listed keys. Nil input
--     returns nil.
[2046] = "儘管歷史上名為 deepcopy，它建立的是一個經過篩選的淺層複本。巢狀的值保留其原始身分，且不會複製來源表格的中繼表格。預設排除 except 值中列出的鍵；invert 為 true 時只包含列出的鍵。輸入為 nil 時傳回 nil。",
-- ccc11c66 English: Create a spell input with suggestions, validation and spell-link support for
--     custom condition widgets. The update callback owns saving a chosen value; add the returned
--     widget to the callback parent.
[2047] = "為自訂條件元件建立一個帶有建議、驗證與法術連結支援的法術輸入框。更新回呼負責儲存所選的值；將傳回的元件新增到回呼的父層。",
-- 4736bce4 English: Create a transient named condition summary. Use {name} for scalar values and
--     {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape
--     literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their
--     percent signs, links, colors or braces. Typed predicate values participate in primary
--     selection. Templates, values and rendered text are bounded; malformed input renders a
--     localized unavailable summary. This changes presentation only and runs no condition
--     observations.
[2048] = "建立一個暫時的具名條件摘要。純量值使用 {name}，判斷的正反兩種措辭使用 {{positive|negative}}；在主要措辭前加上 ! 前綴。字面的雙大括號請跳脫為 {{{{ 和 }}}}。值會依字面插入，不解析其中的百分號、連結、顏色或大括號。具型別的判斷值會參與主要措辭的選擇。範本、值與繪製後的文字都有長度上限；格式錯誤的輸入會繪製為在地化的「無法使用」摘要。這只改變呈現方式，不會執行任何條件觀測。",
-- 7735b638 English: Create a typed comparison predicate for a named condition phrase. Positive
--     wording uses the original captured operator map and negative wording uses the current negated
--     operator map. A primary predicate takes precedence over qualifiers; only the first eligible
--     predicate negates. Unknown operators use the existing operator placeholder. This formats
--     wording without comparing values or evaluating a condition.
[2049] = "為具名條件短語建立一個具型別的比較判斷。肯定措辭使用原先擷取的運算子對應，否定措辭使用目前反轉後的運算子對應。主要判斷優先於限定詞；只有第一個符合條件的判斷會被反轉。未知運算子使用現有的運算子預留位置。這只格式化措辭，不比較值也不評估條件。",
-- ddea308b English: Create an iterator over a sorted snapshot of table keys. Default ordering
--     compares keys; a custom order callback receives the original table and two keys. Values are
--     read from the original table when each key is yielded. The legacy iterator ends when the next
--     captured key is nil or false.
[2050] = "建立一個走訪表格鍵排序快照的迭代器。預設依鍵排序；自訂排序回呼會收到原始表格與兩個鍵。每次產出一個鍵時，值從原始表格中讀取。當下一個擷取的鍵為 nil 或 false 時，舊版迭代器結束。",
-- 629b2567 English: Create native wrapping text that measures its height from its width and font.
--     SetText, SetFont or SetFontObject configure its contents. Add it to the callback parent with
--     parent:AddChild(widget) so layout can track its measured height.
[2051] = "建立原生的自動換行文字，根據其寬度與字型測量高度。SetText、SetFont 或 SetFontObject 用於設定其內容。將其使用 parent:AddChild(widget) 新增到回呼的父層，以便版面能夠追蹤其測得的高度。",
-- c58c9a9a English: Create native wrapping text with optional leading image and pointer callbacks.
--     SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition
--     callback contract. Add it to the callback parent with parent:AddChild(widget); callbacks
--     expire when its lease is released.
[2052] = "建立原生的自動換行文字，可選擇帶有前置圖像與指標回呼。SetImage 與 SetImageSize 用於設定圖像；OnEnter、OnLeave 與 OnClick 使用條件回呼約定。將其使用 parent:AddChild(widget) 新增到回呼的父層；其租用被釋放時回呼會失效。",
-- fa988d31 English: Current evaluation time in seconds from GetTime(), normally evalStart.
[2053] = "目前評估時間，單位為秒，取自 GetTime()，通常為 evalStart。",
-- c7fd7453 English: Current positive visibility distance in yards; nil when unavailable.
[2054] = "目前的正可見距離，單位為碼；無法使用時為 nil。",
-- 574eed72 English: Current unit token whose distance from the player should be observed.
[2055] = "要觀測其與玩家距離的目前單位代碼。",
-- 83a1023e English: Damage/heals arrays of time/value rows; only selected streams are consumed.
[2056] = "由時間/數值列組成的傷害/治療陣列；只會使用所選的資料流。",
-- 38e0b44b English: Decimal places, default zero; negative values round to tens or larger powers of
--     ten.
[2057] = "小數位數，預設為零；負值會捨入到十或更大的十的冪。",
-- c1094708 English: Dense array of keys sorted by associated value.
[2058] = "依對應值排序的鍵的密集陣列。",
-- 7de55bf4 English: Dense array of nonempty text fields.
[2059] = "非空文字欄位的密集陣列。",
-- ba17b32f English: Destination array modified in place.
[2060] = "被原地修改的目標陣列。",
-- 9d65688a English: Display lookup table.
[2061] = "顯示查詢表。",
-- 763bf095 English: Estimate signed health change from weighted damage and healing history. Damage
--     contributes a negative rate and healing a positive rate. Read the live profile window when no
--     window is supplied, use the live clock and legacy rounding service, and preserve the existing
--     weighting and rounded-age calculation. This helper does not validate or sanitize history,
--     clamp timestamps, or guarantee finite results.
[2062] = "根據加權的傷害與治療歷史估算帶正負號的生命力變化。傷害貢獻負速率，治療貢獻正速率。未提供時間區間時讀取即時設定檔中的時間區間，使用即時時鐘與舊版捨入服務，並保留現有的加權與捨入後時長計算。此輔助函式不會驗證或清理歷史，不會截斷時間戳記，也不保證結果有限。",
-- c95e98a7 English: Estimate time until selected health. Cache complete native identity and lazy
--     scalar observations per evaluation pass, while provider, history, window, clock and forecast
--     stay live. Exact target equality returns zero before history work. Preserve deliberate
--     no-estimate false and initialized-zero results for zero or opposite rates; required invalid
--     facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent
--     a partial estimate.
[2063] = "估算距離達到所選生命力的時間。每個評估輪次快取完整的原生身分與惰性純量觀測，而提供者、歷史、時間區間、時鐘與預測保持即時。目標完全相等時，會在處理歷史之前傳回零。對於零速率或反向速率，保留刻意設計的「無估算」false 結果與初始化的零結果；所需資訊無效、溢位或 4096 單位工作量耗盡時為無法使用。絕不修改歷史或捏造部分估算。",
-- 52a17c6c English: Evaluation cache, or nil to bypass caching.
[2064] = "評估快取；為 nil 時略過快取。",
-- 79697e3a English: Evaluation-pass cache for complete unit observations; nil observes directly.
--     Different selected keys reuse the same unit snapshot.
[2065] = "用於完整單位觀測的評估輪次快取；為 nil 時直接觀測。不同的所選鍵會重複使用同一個單位快照。",
-- bd88f3f9 English: Evaluation-pass cache, or nil for fresh observations.
[2066] = "評估輪次快取；為 nil 時重新觀測。",
-- d022fab6 English: Evaluation-pass cache, or nil to observe identity directly. Resource mapping is
--     resolved live on each invocation.
[2067] = "評估輪次快取；為 nil 時直接觀測身分。資源對應在每次呼叫時即時解析。",
-- 0900784b English: Evaluation-pass cache, or nil to observe identity directly. Successful player
--     class observations may use the existing longterm identity cache; resource mapping remains
--     live.
[2068] = "評估輪次快取；為 nil 時直接觀測身分。成功的玩家職業觀測可以使用現有的長期身分快取；資源對應保持即時。",
-- 383aa43c English: Evaluation-pass native observation cache; nil queries afresh.
[2069] = "評估輪次的原生觀測快取；為 nil 時重新查詢。",
-- bf9ecd5c English: Evaluation-pass presence cache only; name, level and provider history remain
--     fresh.
[2070] = "僅為評估輪次的存在性快取；名稱、等級與提供者歷史保持即時。",
-- 2dbf0453 English: Exact helper-owned player, party1..party4 or raid1..raid40 token.
[2071] = "由輔助函式擁有的確切代碼：player、party1..party4 或 raid1..raid40。",
-- 27bda267 English: Exact integral native rune slot from 1 through 6.
[2072] = "確切的整數原生符文欄位，範圍為 1 到 6。",
-- 4fc2d3d1 English: Exact nonempty unit token to observe.
[2073] = "要觀測的確切非空單位代碼。",
-- c590f11f English: Exact nonempty unit token, passed unchanged.
[2074] = "確切的非空單位代碼，原樣傳遞。",
-- fd8065c0 English: Exact readable recipient name recorded for this cast.
[2075] = "為這次施法記錄的確切可讀對象名稱。",
-- b05cf3b2 English: Exact selected unit token; only the literal player token may select the TBC
--     combo transport.
[2076] = "確切的所選單位代碼；只有字面上的 player 代碼可以選擇 TBC 連擊點傳輸方式。",
-- 19306e82 English: Exact selected unit token; player class alone may use the successful longterm
--     cache.
[2077] = "確切的所選單位代碼；只有玩家職業可以使用成功的長期快取。",
-- af7eabaa English: Exact selected unit token; the attacker remains player.
[2078] = "確切的所選單位代碼；攻擊者始終為 player。",
-- c08ce58e English: Exact unit token checked for existence and passed to the selected metadata API.
[2079] = "用於檢查存在性並傳給所選中繼資料 API 的確切單位代碼。",
-- eb750dcd English: Exact unit token passed unchanged to UnitExists and, when required, UnitClass.
[2080] = "原樣傳給 UnitExists 以及（必要時）UnitClass 的確切單位代碼。",
-- 3641c328 English: Exact unit token used for existence and as the recipient of player hostility
--     and threat queries.
[2081] = "用於檢查存在性，並作為玩家敵對與威脅值查詢接收者的確切單位代碼。",
-- 616ee642 English: Exact unit token whose resource should be observed; this does not redirect
--     player or vehicle units.
[2082] = "要觀測其資源的確切單位代碼；這不會重新導向玩家或載具單位。",
-- f89b30c5 English: Exact unit token whose selected flag should be observed.
[2083] = "要觀測其所選標記的確切單位代碼。",
-- bb716e79 English: Exact unit token whose selected resource quantity is requested.
[2084] = "要請求其所選資源數量的確切單位代碼。",
-- d07d5f8c English: Exactly current for UnitPower or maximum for UnitPowerMax.
[2085] = "確切為目前值（UnitPower）或最大值（UnitPowerMax）。",
-- 3234a7b8 English: Exactly current for UnitPower or maximum for UnitPowerMax; no other native
--     query is added.
[2086] = "只能是 current（對應 UnitPower）或 maximum（對應 UnitPowerMax）；不會新增其他原生查詢。",
-- ce5b4817 English: Exactly current for the player/target combo query or maximum for the player
--     capacity query.
[2087] = "只能是 current（對應玩家/目標連擊點查詢）或 maximum（對應玩家上限查詢）。",
-- 01112dbd English: Exactly dead for UnitIsDeadOrGhost, or friendly for UnitIsFriend(player, unit).
[2088] = "只能是 dead（對應 UnitIsDeadOrGhost）或 friendly（對應 UnitIsFriend(player, unit)）。",
-- 572b3dd2 English: Exactly type or school; selects the required subject field without requiring
--     the other.
[2089] = "只能是 type 或 school；選擇所需的主題欄位，而不要求另一個。",
-- 618e2637 English: Existing stored CREATURE key: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT,
--     UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET or GAS_CLUUD.
[2090] = "現有的已儲存 CREATURE 鍵：BEAST、DRAGONKIN、DEMON、ELEMENTAL、GIANT、UNDEAD、HUMANOID、CRITTER、MECHANICAL、OTHER、TOTEM、NONCOMBAT_PET 或 GAS_CLUUD。",
-- 93af5992 English: Explicit finite clock snapshot; signed and fractional values remain valid.
[2091] = "明確的有限時鐘快照；帶正負號與小數值仍然有效。",
-- b6d72a06 English: Explicit finite weighting window; no profile fallback or clamp.
[2092] = "明確的有限加權時間區間；不會改用設定檔或截斷。",
-- 8775b9a4 English: Explicit nonnegative integer power selector, false for a known absent unit, or
--     nil when required data is unavailable.
[2093] = "明確的非負整數能量選擇器；已知單位不存在時為 false，所需資料無法使用時為 nil。",
-- 593273d6 English: Explicit nonnegative integer selector, false for known unit absence, or nil
--     when required data is unavailable.
[2094] = "明確的非負整數選擇器；已知單位不存在時為 false，所需資料無法使用時為 nil。",
-- 18dcc116 English: Explicit readable finite nonnegative integer power selector, including zero.
[2095] = "明確、可讀、有限的非負整數能量選擇器，包括零。",
-- 4cb2bf6f English: Explicit readable finite nonnegative integer power selector.
[2096] = "明確、可讀、有限的非負整數能量選擇器。",
-- cdbf6c56 English: Finite ETA including zero, false for known absence/no estimate, or nil when
--     unavailable.
[2097] = "有限的預計時間（包括零）；已知不存在/無估算時為 false，無法使用時為 nil。",
-- a4382b09 English: Finite final stream age, or nil when unavailable.
[2098] = "有限的最終資料流時長；無法使用時為 nil。",
-- 84e16e8d English: Finite minimum native threat status, preserving signed and fractional
--     thresholds.
[2099] = "有限的最低原生威脅值狀態，保留帶正負號與小數的門檻。",
-- 7e3a2158 English: Finite native creature ID, false for known unit absence, or nil when required
--     observations are unavailable.
[2100] = "有限的原生生物 ID；已知單位不存在時為 false，所需觀測無法使用時為 nil。",
-- 3dd70e07 English: Finite native resource quantity, retaining its sign and fractional part; nil
--     when unavailable.
[2101] = "有限的原生資源數量，保留其正負號與小數部分；無法使用時為 nil。",
-- 3931aa80 English: Finite native threat status, false for known absence/nonenemy/no-threat, or nil
--     for unavailable observations.
[2102] = "有限的原生威脅值狀態；已知不存在/非敵人/無威脅值時為 false，觀測無法使用時為 nil。",
-- 9cb9f6d2 English: Finite nonnegative native health scalar, or nil when unavailable.
[2103] = "有限的非負原生生命力純量；無法使用時為 nil。",
-- aa23a412 English: Finite quantity in whole units with its fractional part; nil when unavailable.
[2104] = "以完整單位表示並保留小數部分的有限數量；無法使用時為 nil。",
-- 29e4a6a2 English: Finite signed combined rate, or nil for unavailable calculation.
[2105] = "有限的帶正負號合併速率；計算無法使用時為 nil。",
-- 94c010ef English: First exact unit token, checked for existence before comparison.
[2106] = "第一個確切的單位代碼，在比較前會檢查其存在性。",
-- 46ec876e English: First table to compare.
[2107] = "要比較的第一個表格。",
-- 13e6df72 English: Format comparison wording with named Boolean alternatives when the operator has
--     a negative form. The primary flag marks the positive form as the primary alternative.
--     Positive operator labels use the captured operator map; negative labels and nullable dispatch
--     retain their live addon APIs.
[2108] = "當運算子有否定形式時，使用命名布林備選項格式化比較措辭。primary 標記會將肯定形式標為主要措辭。肯定運算子標籤使用擷取的運算子對應；否定標籤與可為空分派保留其即時的插件 API。",
-- b0edcb9b English: Fresh finite native clock value, or nil when unavailable.
[2109] = "全新的有限原生時鐘值；無法使用時為 nil。",
-- b3a296d8 English: Fresh readable class filename, or nil when unavailable.
[2110] = "全新的可讀職業檔名；無法使用時為 nil。",
-- 16428e88 English: Fresh readable finite clock, or nil when unavailable.
[2111] = "全新的可讀有限時鐘；無法使用時為 nil。",
-- 2078f2c6 English: Fresh readable record with active, then name or nameReason, remainingSeconds,
--     durationSeconds, interruptible and spellID. Remaining time and duration are in seconds;
--     remaining time is clamped to zero. An unavailable optional field has its own reason; it does
--     not invalidate an active record.
[2112] = "新讀取的可讀記錄，包含 active，然後是 name 或 nameReason、remainingSeconds、durationSeconds、interruptible 與 spellID。剩餘時間與持續時間以秒為單位；剩餘時間最低為零。無法使用的選用欄位有其自身的原因；它不會使活動記錄失效。",
-- 47a58974 English: Fresh readable record with exists and, when present, a positive integer level.
[2113] = "全新的可讀記錄，包含 exists，存在時還包含正整數 level。",
-- a25abeed English: Fresh readable record with exists and, when present, current health. Maximum
--     health is included only when requested.
[2114] = "全新的可讀記錄，包含 exists，存在時還包含目前生命力。僅在請求時才包含最大生命力。",
-- 21290700 English: Fresh readable record with exists and, when present, powerType and finite
--     current quantity. Requested maximum is finite and nonnegative. Quantities may be fractional;
--     current-mode current may be signed.
[2115] = "全新的可讀記錄，包含 exists，存在時還包含 powerType 與有限的目前數量。請求的最大值為有限的非負數。數量可以是小數；current 模式下的目前值可以帶正負號。",
-- 681f8ad6 English: Fresh readable record with finite nonnegative speed, or nil when unavailable.
[2116] = "全新的可讀記錄，包含有限的非負速度；無法使用時為 nil。",
-- abf7477d English: Function or global function name to call.
[2117] = "要呼叫的函式或全域函式名稱。",
-- 9d253f49 English: History record with newest-first damage and heals arrays of time/value entries.
--     Falsy history returns only zero without reading the clock.
[2118] = "歷史記錄，包含以最新者在前的傷害與治療陣列，元素為時間/數值項目。為假值的歷史只傳回零，不會讀取時鐘。",
-- 8deb9947 English: Identifier-keyed scalar values or typed predicates. Strings, finite numbers and
--     booleans are supported; referenced slots must be present. Values are captured when the phrase
--     is created.
[2119] = "以識別碼為鍵的純量值或具型別的判斷。支援字串、有限數字與布林值；被參照的欄位必須存在。值在建立短語時被擷取。",
-- b1c195d7 English: Insert each value visited by ipairs at its corresponding leading index in the
--     destination array. Existing entries shift after the inserted prefix; traversal stops at the
--     first missing source index.
[2120] = "將 ipairs 走訪到的每個值插入到目標陣列中對應的開頭索引處。現有項目會移到插入的前綴之後；走訪在第一個缺少的來源索引處停止。",
-- db2baa62 English: Integral RM statistic selector 1..5, or 6 for effective armor.
[2121] = "整數形式的 RM 屬性選擇器 1..5，或 6 表示有效護甲。",
-- c406e603 English: Iterator yielding a captured key and its current table value, or no values when
--     exhausted.
[2122] = "產出一個擷取的鍵及其目前表格值的迭代器；耗盡時不產出任何值。",
-- ce63ac6d English: Key to look up.
[2123] = "要查詢的鍵。",
-- 3638b5da English: Known active count from zero through the RM scan budget, or nil when
--     unavailable.
[2124] = "已知的活躍計數，範圍為零到 RM 的掃描預算；無法使用時為 nil。",
-- 101d17c0 English: Known nonempty role string, false for known absent unit, or nil when
--     unavailable.
[2125] = "已知的非空職責字串；已知單位不存在時為 false，無法使用時為 nil。",
-- 5194c38b English: Known nonempty role string, or nil when unavailable.
[2126] = "已知的非空職責字串；無法使用時為 nil。",
-- 74c5fd96 English: Known unit presence or absence; nil when the required observation is
--     unavailable.
[2127] = "已知的單位存在或不存在；所需觀測無法使用時為 nil。",
-- 337a2aa3 English: Larger rounded stream age in seconds, not a sample count or proof of continuous
--     observation. Omitted when history is falsy.
[2128] = "較大的捨入後資料流時長（秒），並非樣本數量，也不能證明是連續觀測。歷史為假值時省略。",
-- 289c0861 English: Left operand; use numbers for ordering and divisibility.
[2129] = "左運算元；排序與整除請使用數字。",
-- c6b39836 English: Literal prefix, including an empty prefix.
[2130] = "字面前綴，可以為空前綴。",
-- 8bc05b19 English: Literal suffix, including an empty suffix.
[2131] = "字面後綴，可以為空後綴。",
-- 696821ba English: Live selected talent-group argument, forwarded unchanged as one argument after
--     readability checking.
[2132] = "即時的所選天賦組參數，經可讀性檢查後作為單一參數原樣轉送。",
-- 55c2262c English: Localized complete sentence with named slots and optional explicit predicate
--     alternatives.
[2133] = "帶有命名欄位與選擇性的明確判斷備選項的在地化完整句子。",
-- ebab9399 English: Look up a table key for display, preserving non-nil results; invalid tables,
--     missing keys and nil keys use nullable placeholder text.
[2134] = "查詢表格中的鍵用於顯示，保留非 nil 的結果；無效的表格、缺少的鍵與 nil 鍵會使用可為空預留位置文字。",
-- d27c5ef2 English: Lookup key.
[2135] = "查詢鍵。",
-- d746509f English: Lua pattern character-class separator, default %s for whitespace.
-- %s #1: %s #1: not a placeholder; it is the literal Lua pattern class for whitespace, shown to the user as text, e.g. "default %s for whitespace". Keep %s exactly as written.
[2136] = "Lua 模式的字元類別分隔符，預設為 %s，表示空白字元。",
-- 3aeb0664 English: Mark the positive wording as the primary named alternative.
[2137] = "將肯定措辭標記為主要的命名備選項。",
-- 44dec6d3 English: Matching key, including a false key, or nil when no match exists.
[2138] = "相符的鍵（包括 false 鍵）；不存在相符時為 nil。",
-- 75ef3e00 English: Missing-value display text; omitted uses the localized value placeholder.
[2139] = "缺少值的顯示文字；省略時使用在地化的值預留位置。",
-- 15f81670 English: Native button with label, disabled state and lease-protected callbacks.
[2140] = "帶有標籤、停用狀態與受租用保護回呼的原生按鈕。",
-- 8eb10f5d English: Native directional pad with center reset and lease-protected callbacks.
[2141] = "帶有置中重設與受租用保護回呼的原生方向面板。",
-- bb0ac63a English: Native image control with label, texture, disabled state and callbacks.
[2142] = "帶有標籤、材質、停用狀態與回呼的原生圖像控制項。",
-- 43cf01e1 English: Native interactive text and image control with measured height and disabled
--     state.
[2143] = "帶有測量高度與停用狀態的原生互動式文字與圖像控制項。",
-- 990a6544 English: Native one-based integral active-row index within the 256-row RM scan budget.
[2144] = "在 RM 256 列掃描預算內、從 1 開始的原生整數活躍列索引。",
-- 7e3aed01 English: Native wrapping text control with font, color and alignment methods.
[2145] = "帶有字型、顏色與對齊方法的原生自動換行文字控制項。",
-- d76c2067 English: New shallow filtered table, or nil for nil input.
[2146] = "新的經過篩選的淺層複本表格；輸入為 nil 時為 nil。",
-- 50f7bd28 English: New table with stringified keys and unchanged values.
[2147] = "鍵被字串化、值保持不變的新表格。",
-- f1052f11 English: Newest-first health snapshots containing time, value and max. Falsy input
--     returns only zero without reading the clock.
[2148] = "以最新者在前的生命力快照，包含 time、value 與 max。為假值的輸入只傳回零，不會讀取時鐘。",
-- 7276d3c4 English: No return values. The destination array is modified in place.
[2149] = "沒有傳回值。目標陣列會被原地修改。",
-- 69c24773 English: No return values. The supplied table is modified in place.
[2150] = "沒有傳回值。所提供的表格會被原地修改。",
-- da87cc23 English: Nonempty class filename token to count; no class-token whitelist is applied.
[2151] = "要統計的非空職業檔名代碼；不套用職業代碼白名單。",
-- 3694f9ed English: Nonempty historical school key for resist/immune; unused for runner.
[2152] = "用於 resist/immune 的非空歷史法術類型鍵；runner 不使用。",
-- 7ee44b6f English: Normalized bounded socket snapshot with slots and complete, or nil when the
--     query is unavailable.
[2153] = "標準化的有限插槽快照，包含 slots 與 complete；查詢無法使用時為 nil。",
-- 93ec5fb4 English: Normalized requested subject with finite timeRemaining or timeRemainingReason;
--     nil when the required row or subject is unavailable.
[2154] = "標準化的所請求主題，包含有限的 timeRemaining 或 timeRemainingReason；所需的列或主題無法使用時為 nil。",
-- 7663ebe1 English: Number of entries visited.
[2155] = "走訪到的項目數量。",
-- 7f36a397 English: Number or string to inspect; other types do not match.
[2156] = "要檢查的數字或字串；其他型別不相符。",
-- 4e6ddf17 English: Numeric widget supporting slider bounds, percent display and pending-edit
--     validation.
[2157] = "支援滑桿範圍、百分比顯示與待處理編輯驗證的數值元件。",
-- c8144d6f English: Observation kind: cast or channel. These use different native interruptibility
--     tuple positions.
[2158] = "觀測種類：cast 或 channel。它們使用原生可中斷元組中的不同位置。",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2159] = "觀測、歷史、工作量上限或運算的可用性原因。",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2160] = "為所需的生命力預測重新觀測一次受保護的無參數 GetTime。要求結果可讀且為有限數字；保留帶正負號與小數值，不額外加入單調、整數或非負的限制。不使用時鐘快取或額外的原生查詢。",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2161] = "觀測用戶端以片段回報的點數資源（潘達利亞之謎的燃火餘燼）。目前值確切使用 UnitPower(unit,powerType,true)，最大值確切使用 UnitPowerMax(unit,powerType,true)；結果會除以暴雪的 MAX_POWER_PER_EMBER（10），因此 35 個片段為 3.5。僅限探測政策。缺少、失敗、受限或格式錯誤的資料維持為無法使用；絕不會退回完整單位的查詢。不新增快取。",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2162] = "在已知的用戶端上觀測可讀的原始單位等級。可讀且不存在的單位傳回 exists=false；存在的單位要求 UnitLevel 為正的有限整數。未知的首領等級，以及缺少、失敗、受限或格式錯誤的觀測會傳回 nil 及原因。這不使用有效等級或縮放後的等級。",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2163] = "在探測或受限政策用戶端上觀測所選單位的職責，不發出觀察請求。已知單位不存在時傳回 false。優先使用可呼叫的現代觀察 API，僅當它不可呼叫時才改用舊版；所選 API 失敗時絕不會改用其他 API。要求專精 ID 為正的有限整數，並且只使用確切的單參數 GetSpecializationInfoByID 呼叫的第五個傳回值（職責）。所需資訊缺少、失敗、受限或格式錯誤時為無法使用；可讀的非空未來職責字串保持原樣。",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2164] = "在探測或受限政策用戶端上觀測單位的施法或引導。已知不存在的單位或可讀的非活動結果傳回 active=false。活動記錄包含 name，或在名稱為機密時包含 nameReason（單位仍在施法），以及可獨立取得的 remainingSeconds、durationSeconds、interruptible 與 spellID 欄位；選用欄位無法使用時附帶 remainingReason、durationReason、interruptibleReason 或 spellReason。存在性觀測缺少、失敗或受限時傳回 nil 及原因。",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2165] = "在探測或受限政策用戶端上，從原生 UnitCreatureType 的第二個傳回值觀測生物身分。先檢查確切的 UnitExists(unit)；可讀的 false 會直接傳回 false，不需要也不呼叫生物中繼資料。存在的單位要求可讀的有限數字 ID；未使用的在地化名稱不影響可用性。帶正負號、小數、零以及未來的有限 ID 都會作為已知值保留。所需資訊缺少、失敗、為 nil、受限或格式錯誤時傳回 nil 及原因。不會新增生物列舉、翻譯標題比較或長期快取。",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2166] = "在探測或受限政策用戶端上，觀測確切的所選單位是否死亡或處於鬼魂狀態，或是否對玩家友好。所需觀測缺少、失敗、受限或格式錯誤時為無法使用。單位不存在時為無法使用，而不是否定比對，在 NOT 下同樣如此。不會保留跨輪詢的狀態。",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2167] = "觀測寵物是否確切存在，並可選擇性地觀測其經 GetUnitName 格式化的顯示名稱。僅查詢存在性時從不需要名稱資料。已知不存在時會略過名稱查詢。僅在請求時，存在的寵物才需要可讀的非空名稱；所需觀測缺少、失敗、為 nil、受限或格式錯誤時傳回 nil 及原因。顯示輔助函式只以原有的單一寵物參數呼叫，不改用 UnitName，也不推斷快捷列、生命力或技能狀態。",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2168] = "為點數資源條件觀測確切的所選單位是否存在，並可選擇性地觀測其職業檔名。已知不存在時傳回 exists=false，不讀取職業。存在的單位只在請求時需要 UnitClass 的第二個傳回值；未使用的在地化名稱與 ID 不影響可用性。所需觀測缺少、失敗、受限或格式錯誤時維持為無法使用。這不會選擇資源或快取身分。",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2169] = "在受支援且可讀的用戶端上觀測明確的法力或目前的原始能量資源。資源身分從即時的 PowerType 列舉中選擇；明確法力絕不會改用目前能量條。已知不存在時傳回 exists=false；缺少、失敗、受限或格式錯誤的觀測會傳回 nil 及原因。current 模式下的數量保留帶正負號的原生資源；明確法力為非負。僅在需要時請求最大值；百分比的使用者必須要求最大值為正。",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2170] = "在已驗證的巫妖王之怒、浩劫與重生與潘達利亞之謎用戶端配置上觀測雕紋插槽。傳回 slots 與 complete 標記。每個插槽在已知鎖定或為空時為 active=false，被佔用時為 active=true 並附帶 spellID，無法使用時 active 為 nil 並附帶原因。未知配置與失敗的數量查詢會傳回 nil 及原因。這不會比較物品名稱，也不能證明物品與法術身分的確切對應。",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2171] = "在檢查 UnitExists 後觀測一個所使用的原生單位中繼資料欄位：class 使用 UnitClass 的第二個傳回值，creature 使用在地化的 UnitCreatureType 名稱，classification 使用 UnitClassification。可讀且不存在的單位傳回 false，不查詢中繼資料。未使用的元組欄位不影響可用性；所需的值缺少、失敗、為 nil、受限或格式錯誤時傳回 nil 及原因。不會新增玩家職業、GUID、列舉或翻譯推斷。",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2172] = "觀測一個目前的單位標記：combat 使用 UnitAffectingCombat，enemy 使用以 player 為第一個單位的 UnitIsEnemy，pvp 使用 UnitIsPVP。可讀且不存在的單位傳回 false，不查詢該標記。所需觀測缺少、失敗、受限或格式錯誤時傳回 nil 及原因。這會保留確切的所選單位，不推斷友好、可攻擊或其他單位狀態。",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2173] = "使用只帶單一索引參數的 GetRuneType 觀測一個確切的原生符文欄位。要求類型可讀且為正的有限整數；已知的未來數字類型與所選類型保持區分，死亡符文是一個確切的類型而不是萬用字元。缺少、失敗、受限或格式錯誤的觀測維持為無法使用。不會新增職業、單位、數量或推斷基礎符文的查詢。",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2174] = "觀測一個獨立的無參數玩家標記：stealthed 使用 IsStealthed，control 使用 HasFullControl，outdoors 使用 IsOutdoors。可讀的 true 與 false 保留其含義。所需資料缺少、失敗、為 nil、受限或格式錯誤時傳回 nil 及原因。不會新增存在性、副本或技能可用性的推斷。",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2175] = "觀測一個受保護的無參數 IsInInstance 元組。所需的可讀布林成員值與類型欄位無關：已知在副本外時直接傳回，不解釋未使用的類型；在副本內時傳回可讀的字串類型，或在該次要欄位無法使用時傳回 instanceTypeReason。檢測是否在副本外的呼叫端只需要成員值；在副本內比較類型時必須檢查次要原因。不會新增戶外、區域或單位推斷。",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2176] = "依序觀測所選單位是否存在、是否與玩家敵對，然後觀測玩家在該單位上的威脅值狀態。已知不存在、非敵人以及成功讀取到的 nil 威脅值狀態傳回 false，以保留「無威脅值」判斷。包括零在內的有限狀態數值保留其原有的比較含義。所需資訊缺少、失敗、為 nil、受限或格式錯誤時傳回 nil 及原因。不會新增可攻擊、死亡、戰鬥或載具的推斷。",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2177] = "在受支援的用戶端上觀測可讀的目前生命力，並可選擇性地觀測最大生命力。可讀且不存在的單位傳回 exists=false。缺少、失敗、受限或格式錯誤的觀測會傳回 nil 及原因；它們不能證明單位不存在或得出生命力。",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2178] = "使用一次受保護的無參數 GetShapeshiftForm 呼叫觀測玩家目前的形態。保留每個可讀的有限數字結果，包括零、帶正負號與小數值；不會推斷更嚴格的原生索引範圍。缺少、失敗、為 nil、受限或非有限的資料維持為無法使用。不會新增形態數量、職業、法術 ID、單位或選擇性參數。",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2179] = "只從原生的第二個傳回值觀測有效屬性。在探測或受限政策用戶端上，先查詢確切的 UnitExists(unit)，然後對選擇器 1..5 查詢 UnitStat(unit,stat)，或對選擇器 6 查詢 UnitArmor(unit)。已知不存在時傳回 exists=false；所需資訊缺少、失敗、受限或非有限時傳回 nil。保留有限的帶正負號、小數與零值；忽略所有未使用的元組欄位。1..6 的路由是 RM 的選擇器政策，而非原生值域的限制。",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2180] = "觀測明確選擇的 TBC 玩家連擊點傳輸方式。current 只使用 GetComboPoints(player,target)；maximum 使用帶原始選擇器的 UnitPowerMax(player,powerType)。其他用戶端系列在此無法使用，必須使用其現有的點數能量觀測器。保留可讀的有限帶正負號、小數與零值。缺少、失敗、受限或格式錯誤的資料維持為無法使用；所選的連擊點查詢失敗時絕不會改用 UnitPower。這不會觀測其他角色，也不會新增快取。",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2181] = "在探測或受限政策用戶端上，觀測確切的舊版 GetTalentGroupRole(group) 點號呼叫的第一個職責結果。將可讀的所選天賦組原樣轉送，包括將 nil 作為一個參數；不推斷天賦組範圍、不替換為其他 API，也不查詢玩家單位。完整的舊版主要宣告並未成立。職責資料缺少、失敗、受限、為空或格式錯誤時為無法使用；可讀的非空未來字串保持原樣。",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2182] = "使用一次受保護的無參數點號呼叫，觀測區域 PvP 分類的第一個結果。優先使用可呼叫的 C_PvP.GetZonePVPInfo，僅當現代 API 不可呼叫時才使用全域輔助函式。成功傳回 nil 或沒有傳回值時，會產生一個已知的空記錄；缺少、失敗、受限或格式錯誤的觀測維持為無法使用。可讀的空字串與未來字串保留其確切含義，未使用的傳回欄位不決定可用性。在現代 API 傳回結果或失敗後，絕不切換後端。",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2183] = "在受支援且可讀的用戶端上觀測玩家目前的移動速度。這只針對 player 查詢 GetUnitSpeed，不檢測其他單位，也不重新導向載具擁有權。零表示靜止；正的有限小數速度仍然有效。缺少、失敗、受限或格式錯誤的觀測會傳回 nil 及原因。",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2184] = "在已識別的用戶端系列上觀測單位的存在性。將所選單位原樣傳給一次受保護的 UnitExists 呼叫。保留可讀的 true 與 false；所需觀測缺少、失敗、受限、為 nil 或格式錯誤時傳回 nil 及原因。不會新增身分、可見性、距離或戰鬥狀態的查詢。",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2185] = "使用確切的 UnitExists、UnitCanAttack 與 UnitIsDead 判斷，觀測玩家是否可以攻擊一個未死亡的所選單位。已知不存在或可讀的不可攻擊結果會傳回 false，不查詢死亡狀態。所需觀測缺少、失敗、受限或格式錯誤時傳回 nil 及原因。這不檢測鬼魂狀態、距離、敵對狀態或技能可用性，也不重新導向單位擁有權。",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2186] = "觀測到的職業檔名字串；已知單位不存在時為 false，無法使用時為 nil。",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2187] = "觀測到的成員身分；無法使用時為 nil。",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2188] = "僅限所選資源：target-combo 用於明確的 TBC 玩家備用，power 用於現有的所選單位傳輸方式。",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2189] = "在探測或受限政策用戶端上觀測確切的 UnitExists(unit)，然後僅對存在的單位觀測 UnitGUID(unit)。已知不存在時為 false。存在的身分要求可讀的非空 GUID；所需資訊缺少、失敗、格式錯誤或受限時為無法使用。不會新增生命力、提供者或額外單位的觀測。",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2190] = "class、creature 或 classification 之一；不支援其他中繼資料種類。",
-- f4dbfa56 English: One of combat, enemy or pvp; other flag kinds are not supported.
[2191] = "combat、enemy 或 pvp 之一；不支援其他標記種類。",
-- 6a9d3fdc English: One of stealthed, control or outdoors; no other predicate is invoked.
[2192] = "stealthed、control 或 outdoors 之一；不會呼叫其他判斷。",
-- e7332ebe English: One rounded numeric result from the original formula.
[2193] = "來自原始公式的一個捨入後的數字結果。",
-- ffb1aba4 English: Optional collection of key values selecting entries; its own keys are ignored.
[2194] = "選擇性的鍵值集合，用於選擇項目；其自身的鍵會被忽略。",
-- a4bd9302 English: Optional ordering callback called as order(t, leftKey, rightKey).
[2195] = "選擇性的排序回呼，以 order(t, leftKey, rightKey) 的形式呼叫。",
-- 3a0cafbd English: Optional positive class ID; nil queries the current player class under
--     protection.
[2196] = "選擇性的正數職業 ID；為 nil 時會在保護下查詢目前玩家的職業。",
-- d8e2dd81 English: Original explicit readable finite nonnegative integer combo-resource selector,
--     including zero; retained for the maximum query.
[2197] = "原始的明確、可讀、有限的非負整數連擊資源選擇器（包括零）；保留用於最大值查詢。",
-- 8311cae8 English: Original non-nil lookup result, or a colored placeholder string.
[2198] = "原始的非 nil 查詢結果，或一個帶顏色的預留位置字串。",
-- 32680ed5 English: Original non-nil value, or a colored placeholder string.
[2199] = "原始的非 nil 值，或一個帶顏色的預留位置字串。",
-- 80842131 English: Original rounded-age bucket count, omitted when the result is the lone zero.
[2200] = "原始的取整時長分段數；結果為單獨的零時省略。",
-- 169b03f3 English: Packaged helper from Conditions/spatial.lua.
[2201] = "來自 Conditions/spatial.lua 的內建輔助函式。",
-- 18a2dc4d English: Packaged helper from utils.lua.
[2202] = "來自 utils.lua 的內建輔助函式。",
-- dd1476f6 English: Partial current/maximum record, empty when provider absent, or nil when
--     unavailable.
[2203] = "部分的目前值/最大值記錄；提供者不存在時為空，無法使用時為 nil。",
-- 52076b9c English: Partial record containing ready or readyReason, start or startReason, and
--     duration or durationReason; nil only when the query itself is unavailable.
[2204] = "部分記錄，包含 ready 或 readyReason、start 或 startReason，以及 duration 或 durationReason；僅當查詢本身無法使用時為 nil。",
-- 7001225d English: Pet observation with Boolean exists and, for a requested present pet, name; nil
--     when required data is unavailable.
[2205] = "寵物觀測，包含布林值 exists，對於請求的存在的寵物還包含 name；所需資料無法使用時為 nil。",
-- f4bb093a English: Policy or availability reason for a nil movement observation.
[2206] = "移動觀測為 nil 時的政策或可用性原因。",
-- 7f7f12b8 English: Policy, capability or clock observation availability reason for a nil time.
[2207] = "時間為 nil 時的政策、功能或時鐘觀測可用性原因。",
-- 43794680 English: Policy, capability or required-observation availability reason.
[2208] = "政策、功能或所需觀測的可用性原因。",
-- d35012ad English: Policy, query, capability or required row/subject availability reason for a nil
--     record.
[2209] = "記錄為 nil 時的政策、查詢、功能或所需列/主題的可用性原因。",
-- 59cf373b English: Policy, query-validation or availability reason for a nil metadata observation.
[2210] = "中繼資料觀測為 nil 時的政策、查詢驗證或可用性原因。",
-- 5f9416e7 English: Policy, query-validation or availability reason for a nil pet observation.
[2211] = "寵物觀測為 nil 時的政策、查詢驗證或可用性原因。",
-- 046d5773 English: Policy, query-validation or availability reason for a nil player flag.
[2212] = "玩家標記為 nil 時的政策、查詢驗證或可用性原因。",
-- a9338066 English: Policy, query-validation or availability reason for a nil quantity.
[2213] = "數量為 nil 時的政策、查詢驗證或可用性原因。",
-- bde90d0c English: Policy, query-validation or availability reason for a nil resource observation.
[2214] = "資源觀測為 nil 時的政策、查詢驗證或可用性原因。",
-- cd1d6bc4 English: Policy, query-validation or availability reason for a nil threat observation.
[2215] = "威脅值觀測為 nil 時的政策、查詢驗證或可用性原因。",
-- b963fb2b English: Policy, query-validation or availability reason for a nil unit flag.
[2216] = "單位標記為 nil 時的政策、查詢驗證或可用性原因。",
-- de3eca9c English: Policy, query-validation or availability reason for nil attackability.
[2217] = "可攻擊性為 nil 時的政策、查詢驗證或可用性原因。",
-- e1be06fc English: Policy, query-validation or identity/selector availability reason for a nil
--     selector.
[2218] = "選擇器為 nil 時的政策、查詢驗證或身分/選擇器可用性原因。",
-- a82bb017 English: Policy, query-validation or required observation availability reason for a nil
--     quantity.
[2219] = "數量為 nil 時的政策、查詢驗證或所需觀測的可用性原因。",
-- 3422d50e English: Policy, query-validation or required observation availability reason for a nil
--     record.
[2220] = "記錄為 nil 時的政策、查詢驗證或所需觀測的可用性原因。",
-- 6d8971dd English: Policy, query-validation or required-observation availability reason for a nil
--     ID.
[2221] = "ID 為 nil 時的政策、查詢驗證或所需觀測的可用性原因。",
-- abb38505 English: Policy, query-validation or required-observation availability reason for a nil
--     match.
[2222] = "比對結果為 nil 時的政策、查詢驗證或所需觀測的可用性原因。",
-- 4be03f57 English: Policy, slot-validation or required observation availability reason for a nil
--     type.
[2223] = "類型為 nil 時的政策、欄位驗證或所需觀測的可用性原因。",
-- 07a2f2a4 English: Policy, slot-validation, capability or native-call availability reason for a
--     nil record.
[2224] = "記錄為 nil 時的政策、欄位驗證、功能或原生呼叫的可用性原因。",
-- 57d4e2a6 English: Policy, snapshot, identity or threat observation availability reason.
[2225] = "政策、快照、身分或威脅值觀測的可用性原因。",
-- 88172c69 English: Policy, token-validation or availability reason for a nil identity result.
[2226] = "身分結果為 nil 時的政策、代碼驗證或可用性原因。",
-- 41f7dc66 English: Policy, validation or availability reason for a nil health observation.
[2227] = "生命力觀測為 nil 時的政策、驗證或可用性原因。",
-- cc67968e English: Policy, validation or availability reason for a nil snapshot.
[2228] = "快照為 nil 時的政策、驗證或可用性原因。",
-- 84bacc88 English: Policy, validation or observation availability reason.
[2229] = "政策、驗證或觀測的可用性原因。",
-- 702b5d1d English: Policy, validation or required observation availability reason.
[2230] = "政策、驗證或所需觀測的可用性原因。",
-- e3a0a3ce English: Positive integer glyph item ID stored by the condition; arrays, item-set keys
--     and spell IDs are not item references.
[2231] = "條件中儲存的正整數雕紋物品 ID；陣列、物品組鍵與法術 ID 不是物品參照。",
-- c7e5f035 English: Positive integer level, false for a known absent unit, or nil when unavailable.
[2232] = "正整數等級；已知單位不存在時為 false，無法使用時為 nil。",
-- 2ce665d6 English: Positive integer spell ID, not a spell-book slot.
[2233] = "正整數法術 ID，而不是法術書欄位。",
-- 37be242f English: Positive item ID or native-recognized item name/link to classify.
[2234] = "要分類的正數物品 ID，或原生可辨識的物品名稱/連結。",
-- eac23024 English: Predicate that validates the proposed spell value.
[2235] = "驗證擬議法術值的判斷函式。",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2236] = "存在時為 GUID；已知不存在時為 false，無法使用時為 nil。",
-- 5825055c English: Provider, validation or observation availability reason.
[2237] = "提供者、驗證或觀測的可用性原因。",
-- e78c7309 English: Query, policy or observation availability reason.
[2238] = "查詢、政策或觀測的可用性原因。",
-- b79b336b English: RM comparison operator identifier; missing labels use the operator placeholder.
[2239] = "RM 比較運算子識別碼；缺少的標籤使用運算子預留位置。",
-- 505c9dde English: RM operator identifier.
[2240] = "RM 運算子識別碼。",
-- a3bcccb3 English: Range record with applicable and, when applicable, inRange; nil when
--     unavailable.
[2241] = "距離記錄，包含 applicable，適用時還包含 inRange；無法使用時為 nil。",
-- a18d0c99 English: Read a fresh protected UnitClass player observation for rotation ownership.
--     Consume only the readable nonempty class filename from return two. No existence, level,
--     vehicle, family or combat-policy read is added, and no result persists across calls. Core
--     ownership still validates the class token and character key separately; overridden context
--     providers retain their complete original path.
[2242] = "為循環擁有權讀取一次全新的受保護 UnitClass 玩家觀測。只使用第二個傳回值中可讀的非空職業檔名。不會新增存在性、等級、載具、用戶端系列或戰鬥政策的讀取，結果也不會跨呼叫保留。核心擁有權仍會分別驗證職業代碼與角色鍵；被覆蓋的情境提供者保留其完整的原有路徑。",
-- 97b3a051 English: Read a fresh protected zero-argument GetTime for rune cooldown arithmetic.
--     Require a readable finite number. This observation is deliberately uncached; callers preserve
--     the original clock-before-scan order and require its value only when a matching rune needs
--     timing. No evaluation-start substitution or inferred time is supplied.
[2243] = "為符文冷卻運算讀取一次全新的受保護無參數 GetTime。要求結果可讀且為有限數字。此觀測刻意不快取；呼叫端保留原有的「先讀時鐘再掃描」順序，並且只在有相符的符文需要計時時才要求其值。不會以評估開始時間替代或推斷時間。",
-- 3b2652a8 English: Read a lazy health scalar after a separate identity gate. Kind current uses
--     exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy
--     clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID
--     call or alternate tuple fallback is added.
[2244] = "在另外的身分檢查之後讀取惰性的生命力純量。current 種類使用確切的 UnitHealth(unit)；maximum 使用確切的 UnitHealthMax(unit)。探測或受限政策用戶端接受可讀的有限非負數字（包括零）。不會重複呼叫存在性/GUID 查詢，也不會改用其他元組。",
-- cd858e26 English: Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime,
--     cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data
--     return nil with a reason.
[2245] = "讀取標準化的充能記錄：currentCharges、maxCharges、cooldownStartTime、cooldownDuration、chargeModRate 與 isActive。不受支援的法術或受限的用戶端資料會傳回 nil 及原因。",
-- 3ba4fbdf English: Read a specified unit membership in the player party or raid. True raidOnly
--     queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds
--     to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer
--     raid index1..40 means true. Names are passed unchanged to native APIs; native name-query
--     acceptance requires client qualification.
[2246] = "讀取指定單位是否屬於玩家的隊伍或團隊。raidOnly 為 true 時只查詢 UnitInRaid；否則 UnitInParty 結果為 true 時直接傳回，為 false 時繼續查詢 UnitInRaid，未知時維持為無法使用。可讀的 nil 團隊索引表示 false；整數團隊索引 1..40 表示 true。名稱會原樣傳給原生 API；原生 API 是否接受名稱查詢需視用戶端而定。",
-- 3db7feb7 English: Read and normalize a spell cooldown across supported clients. The returned
--     record contains startTime, duration, isEnabled and modRate. The timestamps and duration
--     already describe expiration in GetTime() seconds; do not divide them by modRate. When the
--     client hides the times (Retail and Forever in combat) the record is nil with reason
--     restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when
--     they can be read.
[2247] = "讀取各支援用戶端的法術冷卻並將其正規化。傳回的記錄包含 startTime、duration、isEnabled 與 modRate。時間戳記與持續時間已經以 GetTime() 秒數描述到期時間；不要再除以 modRate。當用戶端隱藏時間時（正式版與永久的戰鬥中），記錄為 nil，原因為 restricted-value，在可以讀取時其後會附上永不為機密的 isEnabled、isActive 與 isOnGCD 旗標。",
-- 4ae0aa42 English: Read normalized native item classification metadata. The record contains
--     canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip
--     location token, when it is readable and nonempty; it does not require loaded item display
--     text. Missing, failed, malformed or restricted metadata returns nil with a reason.
[2248] = "讀取正規化的原生物品分類中繼資料。記錄包含正規的 itemID、classID 與 subClassID，以及在可讀且非空時的 equipLoc（未在地化的 INVTYPE_* 裝備位置標記）；不要求物品顯示文字已載入。中繼資料缺少、失敗、格式錯誤或受限時傳回 nil 及原因。",
-- 5286a3fe English: Read one documented active loss-of-control row by its native index and
--     requested subject kind. Type queries require only the readable control type string; school
--     queries require only the readable finite nonnegative integer school mask. Optional timing is
--     returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject
--     does not require a usable timer. Missing rows are unavailable snapshot observations. No
--     display fields, inferred deadline, duration sum, maximum or native alias fallback is used.
[2249] = "依原生索引與所請求的主題種類，讀取一條有說明文件的活躍失去控制記錄列。type 查詢只需要可讀的控制類型字串；school 查詢只需要可讀的有限非負整數法術類型遮罩。選擇性的計時以有限的 timeRemaining 或逐欄位的明確原因傳回，因此不相關的主題不需要可用的計時器。缺少的列是無法使用的快照觀測。不會使用顯示欄位、推斷的截止時間、持續時間總和、最大值或原生別名備用方案。",
-- 5a423c22 English: Read one explicitly selected point-resource quantity with an exact two-argument
--     UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or
--     actor remapping occurs. Preserve finite signed, fractional and zero quantities without
--     clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and
--     maximum are separate observations so callers can share current snapshots while requesting
--     maximum lazily.
[2250] = "使用確切的雙參數 UnitPower 或 UnitPowerMax 查詢，讀取一個明確選擇的點數資源數量。選擇器為必要；不會推斷主要資源或重新對應角色。保留有限的帶正負號、小數與零數量，不進行截斷。缺少、失敗、受限或非有限的資料維持為無法使用。目前值與最大值是分開的觀測，因此呼叫端可以共用目前值快照，同時依需要延遲請求最大值。",
-- 9f37d74c English: Read one protected GetRuneCooldown tuple for an exact native slot. Normalize
--     ready, start and duration independently: ready requires a readable Boolean, while each time
--     requires a readable finite number and preserves signed, fractional and zero values. Every
--     unavailable field carries its own reason. A successful empty tuple yields a partial record;
--     missing capability, policy or native-call failure yields nil. Never infer ready from timing
--     or timing from ready. Cache this complete record at the caller to share one observation
--     between rune-count and cooldown predicates.
[2251] = "為一個確切的原生欄位讀取一次受保護的 GetRuneCooldown 元組。分別標準化 ready、start 與 duration：ready 需要可讀的布林值，而每個時間值需要可讀的有限數字，並保留帶正負號、小數與零值。每個無法使用的欄位都附帶其自己的原因。成功傳回空元組時會產生部分記錄；缺少功能、政策或原生呼叫失敗時傳回 nil。絕不從計時推斷 ready，也不從 ready 推斷計時。請在呼叫端快取這份完整記錄，以便在符文計數與冷卻判斷之間共用一次觀測。",
-- 0ab0e9af English: Read optional MobInfo2 historical observations on probe- and restricted-policy
--     clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one
--     and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation.
--     Known absent units and successful unrecorded nil or omitted history remain distinct from
--     unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs
--     and missing-Hits default one. Positive resistance ratios must be finite; complete immunity
--     consumes finite Hits while partial immunity needs only its negative school observation. Never
--     infer native resistance or borrow old records.
[2252] = "在探測或受限政策用戶端上讀取選擇性的 MobInfo2 歷史觀測。只快取確切的所選單位存在性；UnitName 的第一個結果、UnitLevel 的第一個結果以及三參數的 MI2_GetMobData(name,level,unit) 點號呼叫每次都會重新取得。已知不存在的單位，以及成功傳回的未記錄的 nil 或省略的歷史，與無法使用的原生/提供者資訊保持區分。保留可讀的 runner 純量真值、法術類型正負號以及缺少 Hits 時預設為一。正的抗性比例必須有限；完全免疫會使用有限的 Hits，而部分免疫只需要其負值的法術類型觀測。絕不推斷原生抗性或借用舊記錄。",
-- a27fc0e3 English: Read optional RealMobHealth using its exact one-argument dot call. Absent
--     nil/false namespace returns an empty record. Normalize current and maximum independently:
--     nil/false fields permit native fallback, numeric zero remains present. Malformed, failed,
--     restricted, negative or nonfinite consumed provider facts are unavailable. No provider or
--     stale fallback cache is used.
[2253] = "使用確切的單參數點號呼叫讀取選擇性的 RealMobHealth。命名空間不存在（nil/false）時傳回空記錄。分別標準化目前值與最大值：nil/false 欄位允許改用原生值，數字零仍視為存在。所使用的提供者資訊格式錯誤、失敗、受限、為負或非有限時為無法使用。不使用提供者或過期的備用快取。",
-- 0a7395cc English: Read public group membership on identified client families. Unknown clients are
--     unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native
--     default group category. A readable false result stays false. Missing, failed, malformed or
--     restricted observations return nil with a reason.
[2254] = "在已識別的用戶端系列上讀取公開的隊伍成員身分。未知用戶端不受支援。raidOnly 為 true 時檢查 IsInRaid；為 false 或 nil 時使用原生預設的隊伍類別檢查 IsInGroup。可讀的 false 結果維持為 false。缺少、失敗、格式錯誤或受限的觀測會傳回 nil 及原因。",
-- 4a264ad3 English: Read public roster identity on identified client families. Input routing is
--     limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that
--     exact one-argument token first; known false returns false without querying class. For a
--     present unit, consume only UnitClass return two as a readable nonempty class filename string,
--     without a class enum restriction. Missing, failed, malformed or restricted required facts
--     return nil with a reason.
[2255] = "在已識別的用戶端系列上讀取公開的名單身分。輸入路由僅限 player、party1 到 party4，以及 raid1 到 raid40。先以該確切的單參數代碼呼叫 UnitExists；已知為 false 時直接傳回 false，不查詢職業。對於存在的單位，只使用 UnitClass 的第二個傳回值作為可讀的非空職業檔名字串，不限制職業列舉。所需資訊缺少、失敗、格式錯誤或受限時傳回 nil 及原因。",
-- 1f3c0a57 English: Read spell-specific range for a unit using the appropriate client API or
--     spell-book slot. A spell without a range restriction returns applicable=false; otherwise
--     applicable=true and inRange records whether the unit is in range. Unknown or inaccessible
--     observations return nil with a reason.
[2256] = "使用適當的用戶端 API 或法術書欄位，讀取某個單位針對特定法術的距離。沒有距離限制的法術傳回 applicable=false；否則 applicable=true，inRange 記錄該單位是否在距離內。未知或無法存取的觀測會傳回 nil 及原因。",
-- d3d07abb English: Read the current positive nameplate visibility distance using the supported
--     CVar API. This limits a Distance Count query; it does not prove that all nearby units have
--     been observed. Missing, malformed, restricted or failed observations return nil with a
--     reason.
[2257] = "使用受支援的 CVar API 讀取目前正的名條可見距離。這會限制「距離內計數」查詢；它不能證明所有附近的單位都已被觀測到。缺少、格式錯誤、受限或失敗的觀測會傳回 nil 及原因。",
-- f4bc8da4 English: Read the documented active loss-of-control count with a protected zero-argument
--     dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and
--     does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that
--     resource budget; this is not a declared native maximum. Required missing, failed, restricted
--     or malformed observations remain unavailable.
[2258] = "使用受保護的無參數點號呼叫，讀取有說明文件的活躍失去控制數量。要求結果可讀且為有限的非負整數。零表示一次完整的空掃描，不需要列 API。RM 將掃描限制為 256 列，超出該資源預算時傳回無法使用；這並不是原生宣告的最大值。所需觀測缺少、失敗、受限或格式錯誤時維持為無法使用。",
-- 597a72b9 English: Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This
--     is distinct from a current or queued cast. Modern clients receive the exact spell ID; a
--     legacy query resolves the player spell-book slot first. Restricted client policies,
--     unreadable results and unavailable book slots return nil with a reason. This observes state
--     and never starts or stops a spell.
[2259] = "讀取玩家某個法術（例如射擊或自動射擊）的自動重複狀態。這與目前或佇列中的施法不同。現代用戶端會收到確切的法術 ID；舊版查詢會先解析玩家的法術書欄位。受限的用戶端政策、無法讀取的結果以及無法使用的法術書欄位會傳回 nil 及原因。這只觀測狀態，從不開始或停止法術。",
-- 89759fd9 English: Read the public LibRangeCheck interval for a unit. A successful upper bound is
--     inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither
--     bound is an exact distance, and a missing upper bound is not proof that the unit is outside
--     every radius. Unavailable, malformed, restricted or failed observations return nil with a
--     reason.
[2260] = "讀取某個單位的公開 LibRangeCheck 距離區間。成功的上限是包含的；正的失敗下限是嚴格的。零下限是合成的。兩個邊界都不是精確距離，缺少上限也不能證明該單位在所有半徑之外。無法使用、格式錯誤、受限或失敗的觀測會傳回 nil 及原因。",
-- 41e0213a English: Readability authority for consumed values.
[2261] = "所使用值的可讀性判定依據。",
-- 7f7e5283 English: Readable canonical item classification record (itemID, classID, subClassID and
--     optional equipLoc), or nil when unavailable.
[2262] = "可讀的正規物品分類記錄（itemID、classID、subClassID 與選用的 equipLoc），無法使用時為 nil。",
-- 708f11a6 English: Readable canonical itemID/classID/subClassID record when the item is a glyph
--     for the requested class; nil for invalid or unavailable metadata.
[2263] = "當物品是所請求職業的雕紋時，傳回可讀的標準 itemID/classID/subClassID 記錄；中繼資料無效或無法使用時為 nil。",
-- b7b27422 English: Readable charge record, or nil when unavailable.
[2264] = "可讀的充能記錄；無法使用時為 nil。",
-- 5274b7b7 English: Readable consumed metadata string, false for a known absent unit, or nil when
--     required data is unavailable.
[2265] = "可讀的所使用中繼資料字串；已知單位不存在時為 false，所需資料無法使用時為 nil。",
-- 041c7f05 English: Readable cooldown record, or nil when unavailable.
[2266] = "可讀的冷卻記錄；無法使用時為 nil。",
-- c171ab16 English: Readable current state, or nil when unavailable.
[2267] = "可讀的目前狀態；無法使用時為 nil。",
-- ea709ff8 English: Readable finite current-form observation, including zero for the current
--     unshifted comparison; nil when unavailable.
[2268] = "可讀的有限目前形態觀測，包括與目前未變形狀態比較時的零；無法使用時為 nil。",
-- 5fe2cef3 English: Readable finite positive integral rune type, or nil when unavailable.
[2269] = "可讀的有限正整數符文類型；無法使用時為 nil。",
-- 243ee644 English: Readable interval with optional minimum and maximum bounds in yards. At least
--     one bound is present; nil when unavailable.
[2270] = "可讀的區間，帶有選擇性的最小與最大邊界（碼）。至少存在一個邊界；無法使用時為 nil。",
-- 7c9763dd English: Readable nonempty selected unit token, passed unchanged as the single argument
--     to existence and creature metadata queries.
[2271] = "可讀的非空所選單位代碼，作為單一參數原樣傳給存在性與生物中繼資料查詢。",
-- 2ce03ebb English: Readable nonempty unit token or native-recognized name, passed unchanged.
[2272] = "可讀的非空單位代碼或原生可辨識的名稱，原樣傳遞。",
-- 30a14f21 English: Readable nonempty unit token to match, unchanged in the native observation.
[2273] = "要比對的可讀非空單位代碼，在原生觀測中保持不變。",
-- 4421ce67 English: Readable nonempty unit token, passed unchanged as the single native argument.
[2274] = "可讀的非空單位代碼，作為單一原生參數原樣傳遞。",
-- 831ff884 English: Readable record with Boolean exists and the requested class filename when
--     present; nil when required data is unavailable.
[2275] = "可讀記錄，包含布林值 exists，存在時還包含所請求的職業檔名；所需資料無法使用時為 nil。",
-- e5d5a0bd English: Readable selected flag or nil when required data is unavailable.
[2276] = "可讀的所選標記；所需資料無法使用時為 nil。",
-- ae99174e English: Readable selected flag, false for a known absent unit, or nil when a required
--     observation is unavailable.
[2277] = "可讀的所選標記；已知單位不存在時為 false，所需觀測無法使用時為 nil。",
-- 15d71981 English: Readable unit equality, false for a known absent first unit, or nil when
--     required observations are unavailable.
[2278] = "可讀的單位相等結果；已知第一個單位不存在時為 false，所需觀測無法使用時為 nil。",
-- c72ce8bc English: Record with exists=false, or exists=true and finite value; nil when
--     unavailable.
[2279] = "記錄為 exists=false，或 exists=true 並帶有有限的 value；無法使用時為 nil。",
-- bbdbf34c English: Record with exists=false; recorded=false for known no history; or runner,
--     ratio, or immune with hits/hitsReason. Nil means a required observation is unavailable.
[2280] = "記錄為 exists=false；已知沒有歷史時為 recorded=false；或者為 runner、ratio 或 immune，並帶有 hits/hitsReason。nil 表示所需觀測無法使用。",
-- d2443dc7 English: Record with inInstance and, when inside, instanceType or instanceTypeReason;
--     nil when membership is unavailable.
[2281] = "記錄包含 inInstance，在副本內時還包含 instanceType 或 instanceTypeReason；成員值無法使用時為 nil。",
-- b2c4007b English: Reference input kind, such as Spec_EditBox, used for spell suggestions.
[2282] = "用於法術建議的參照輸入種類，例如 Spec_EditBox。",
-- 27542d97 English: Remove entries in place, preserving only keys listed among except values by
--     default. With invert true, remove listed keys and retain unlisted keys. Without an exception
--     list, the default removes every entry and invert true retains every entry. Nil input does
--     nothing.
[2283] = "原地移除項目，預設只保留 except 值中列出的鍵。invert 為 true 時，移除列出的鍵並保留未列出的鍵。沒有例外清單時，預設會移除所有項目，而 invert 為 true 時會保留所有項目。輸入為 nil 時不執行任何操作。",
-- e6ab096c English: Remove leading and trailing Lua-pattern whitespace from a string.
[2284] = "移除字串開頭與結尾符合 Lua 模式的空白字元。",
-- a3fc9f6e English: Resolve a readable raw unit level for condition evaluation. Known absence
--     returns false; unavailable observations return nil with a reason. Cache observations within
--     the supplied evaluation pass. Only valid player levels are retained between passes until a
--     skill, profile or level refresh.
[2285] = "為條件評估解析可讀的原始單位等級。已知不存在時傳回 false；觀測無法使用時傳回 nil 及原因。在所提供的評估輪次內快取觀測。只有有效的玩家等級會在輪次之間保留，直到技能、設定檔或等級更新。",
-- 1be3efe7 English: Resolve an exact cast-recipient name against the current bounded party or raid
--     roster, then observe membership through a unit token. Missing, ambiguous or changing roster
--     data remains unavailable; never reads the selected target or retains state across casts.
[2286] = "將確切的施法對象名稱與目前有限的隊伍或團隊名單進行比對，然後透過單位代碼觀測其成員身分。名單資料缺少、含義不明確或正在變化時維持為無法使用；絕不讀取所選目標，也不在施法之間保留狀態。",
-- bf87a408 English: Resolve point resources using the original live class mapping and identity
--     cache, with an explicit TBC player ComboPoints-fallback transport policy. A player fallback
--     matching the readable raw Enum.PowerType table and ComboPoints value captured at module load
--     selects target-combo; explicit class-map entries, other actors and other families retain
--     power. Replaced, inherited or unprovable fallback provenance retains power. This versioned
--     policy does not claim native UnitPower is broken or equivalent. Known unit absence returns
--     false; unavailable required observations return nil with a reason. No current or maximum
--     quantity is queried here.
[2287] = "使用原有的即時職業對應與身分快取解析點數資源，並採用明確的 TBC 玩家 ComboPoints 備用傳輸政策。若玩家備用與模組載入時擷取的可讀原始 Enum.PowerType 表格與 ComboPoints 值相符，則選擇 target-combo；明確的職業對應項目、其他角色與其他用戶端系列保留 power。被取代、繼承或無法證明來源的備用保留 power。此帶版本的政策並不聲稱原生 UnitPower 有問題或與之等效。已知單位不存在時傳回 false；所需觀測無法使用時傳回 nil 及原因。此處不查詢目前值或最大值。",
-- b9173e02 English: Resolve the selected unit point-resource selector using the live
--     class-to-resource map and ComboPoints fallback. Known absence returns false; unavailable
--     required identity or selector data returns nil with a reason. Share complete identity
--     observations within the evaluation pass. Only successful player class observations persist in
--     the current longterm cache, tied to the native UnitClass identity; existence is refreshed
--     each pass. This selects a resource without reading its current or maximum quantity.
[2288] = "使用即時的職業到資源對應與 ComboPoints 備用，解析所選單位的點數資源選擇器。已知不存在時傳回 false；所需的身分或選擇器資料無法使用時傳回 nil 及原因。在評估輪次內共用完整的身分觀測。只有成功的玩家職業觀測會保留在目前的長期快取中，並與原生 UnitClass 身分綁定；存在性在每個輪次都會更新。這只選擇資源，不讀取其目前值或最大值。",
-- 718644e5 English: Resolve the spell identifier stored by a condition. With exact rank enabled the
--     supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank
--     through the spell catalog. Returns nil and an availability reason if resolution cannot be
--     completed.
[2289] = "解析條件中儲存的法術識別碼。啟用精確等級時會保留所提供的 ID；否則在有等級的經典版用戶端上，會透過法術目錄解析目前已知的等級。無法完成解析時傳回 nil 與可用性原因。",
-- 1d0d55d1 English: Resolved spell ID, or nil when unavailable.
[2290] = "解析後的法術 ID；無法使用時為 nil。",
-- 6ffafa71 English: Resolver mapping a typed spell name to its ID.
[2291] = "將輸入的法術名稱對應到其 ID 的解析器。",
-- 09cbb92e English: Return a present value unchanged, or a red display placeholder for nil. Use for
--     readable condition labels, not as a boolean fallback.
[2292] = "原樣傳回存在的值；為 nil 時傳回紅色的顯示預留位置。用於可讀的條件標籤，而不是作為布林值的備用。",
-- d42a9ff5 English: Return the first key whose value equals the supplied value during pairs
--     traversal. Nil or false input tables and absent values return nil. Multiple matching keys
--     have no guaranteed selection order.
[2293] = "在 pairs 走訪過程中傳回第一個值等於所提供值的鍵。輸入表格為 nil 或 false 以及值不存在時傳回 nil。有多個相符的鍵時，選擇順序不確定。",
-- 3f5f3e62 English: Right operand; DIVISIBLE requires a nonzero divisor.
[2294] = "右運算元；DIVISIBLE 要求除數不為零。",
-- 6734885b English: Rotation Master addon instance (implicit with colon calls).
[2295] = "Rotation Master 插件實例（使用冒號呼叫時隱含傳入）。",
-- 46daa133 English: Rotation Master platform adapter (implicit with colon calls).
[2296] = "Rotation Master 平台轉接器（使用冒號呼叫時隱含傳入）。",
-- f0f9c415 English: Rotation Master platform adapter. A dot reference requires addon.Platform as
--     the first argument; a colon call supplies it implicitly.
[2297] = "Rotation Master 平台轉接器。點號參照需要將 addon.Platform 作為第一個參數；冒號呼叫會隱含提供它。",
-- 3f1284ef English: Round with the existing floor(num * 10^places + 0.5) / 10^places formula.
