[2351] = "身分完全相符時為 true；已知不存在或不相符時為 false；所需資料或查詢無法使用時為 nil。",
-- 3286d546 English: True includes only listed entries; false or nil excludes listed entries.
[2352] = "為 true 時只包含列出的項目；為 false 或 nil 時排除列出的項目。",
