[2354] = "為 true 時，在已知團隊成員身分為 true 時允許使用團隊名單；為 false 或 nil 時使用單人或隊伍名單。",
-- 9865f6c6 English: True removes listed entries; false or nil preserves only listed entries.
[2355] = "為 true 時移除列出的項目；為 false 或 nil 時只保留列出的項目。",
