-- %s #1: %s #1: either "enemies" or "allies", e.g. "enemies"
-- %s #2: %s #2: the distance in yards, e.g. 10
[2873] = "%s在 %s 碼內的數量",
-- f9d6358c English: Number of %ss in the %s
-- %s #1: %s #1: the class name, e.g. "Mage" (the "s" after %s is a plural ending in English)
-- %s #2: %s #2: the group, "Party" or "Raid", e.g. "Raid"
[2874] = "%s的數量（在%s中）",
-- 796861d3 English: the time remaining on %s channel
-- %s #1: %s #1: the unit, in the possessive, e.g. "your target's" or "your"
[2875] = "%s法術引導的剩餘時間",
-- 029b1c92 English: the time remaining on %s cast
-- %s #1: %s #1: the unit, in the possessive, e.g. "your target's" or "your"
[2876] = "%s法術施放的剩餘時間",
-- 4bca01ec English: no PVP
-- Context: Option in the zone PVP dropdown and its summary: the zone has no PVP rules.
[2877] = "無 PvP",
-- 5e23ec6a English: Mode
-- Context: Label of the dropdown in the zone PVP condition: the zone's PVP status. Also a help
--     heading.
[2878] = "模式",
-- d50c7904 English: Other (scenario)
-- Context: Option in the instance type dropdown and its summary: the instance is none of the usual
--     types (a scenario).
[2879] = "其他（事件）",
-- f6fe5e59 English: SubZone
-- Context: Checkbox in the zone condition: compare the sub zone instead of the zone name. Also a
--     help heading.
[2880] = "子區域",
-- 2c7564b7 English: %s (set %d)
-- Context: Item set name with its number: first %s is the set name, %d its set number.
-- %s #1: %s #1: the name of the set bonus (item set), e.g. "Plate of the Dread Lord"
-- %d #2: %d #2: the item set ID, e.g. 1234
[2881] = "%s（套裝 %d）",
-- eb179560 English: %s, %d equipped
-- Context: Item set entry in the dropdown of sets you wear: first %s is the set label, %d how many
--     pieces are equipped.
-- %s #1: %s #1: the item set, as its name and ID or "item set 1234", e.g. "Plate of the Dread Lord (set 1234)"
-- %d #2: %d #2: how many pieces of the set are equipped, e.g. 4
[2882] = "%s，已裝備 %d 件",
-- d5c50d7b English: <action bar>
-- Context: Placeholder in the action context summary shown until an action bar is chosen; keep the
--     angle brackets.
[2883] = "<快捷列>",
-- fbf90b5a English: <enchant>
-- Context: Placeholder in the weapon enchant summary shown until an enchant ID is entered; keep the
--     angle brackets.
[2884] = "<附魔>",
-- 23127ea1 English: <item set>
-- Context: Placeholder in item set summaries shown until a set is chosen; keep the angle brackets.
[2885] = "<物品組>",
-- 7c027705 English: A rotation of your own is used only on your own bar unless its switch condition
--     requires another action context with this condition; it is then used, and its buttons found,
--     while that bar is up.
[2886] = "你自己的循環只用於你自己的快捷列，除非它的切換條件透過此條件要求另一種動作情境；此時它會在那個快捷列顯示期間被使用，並在其上尋找按鈕。",
-- fcefef14 English: Currently: no temporary enchant
[2887] = "目前：無暫時附魔",
-- f1ce6167 English: Currently: temporary enchant %d
-- %d #1: %d #1: the ID of the temporary weapon enchant now active, e.g. 5400
[2888] = "目前：暫時附魔 %d",
-- ef4a5266 English: Enchant ID
-- Context: Label of the edit box in the weapon enchant condition: the numeric ID of the temporary
--     enchant. Also a help heading.
[2889] = "附魔 ID",
-- 77078c59 English: Equipped Sets
-- Context: Label of the dropdown in the item set condition listing the sets you currently wear.
[2890] = "已裝備的套裝",
-- 4eb9c836 English: Item Set ID
-- Context: Label of the edit box in the item set condition: the numeric ID of an item set. Also a
--     help heading.
[2891] = "套裝 ID",
-- 27e95eae English: Matches the bar you are acting through: your own, a vehicle, a possessed (mind
--     controlled) unit, an override bar, or a pet battle. Vehicles and override bars exist from
--     Wrath, pet battles only on Retail.
[2892] = "比對你目前操作所用的快捷列：你自己的、載具、被控制（精神控制）的單位、覆蓋快捷列或寵物對戰。載具與覆蓋快捷列從巫妖王之怒開始存在，寵物對戰僅在正式版中存在。",
-- dd05d0e2 English: Pieces
-- Context: Label of the comparison in the item set condition: number of set pieces equipped. Also a
--     help heading.
[2893] = "件數",
-- 4f9a6625 English: The game's item set (for example a tier set). Sets you are wearing are offered
--     in the list; the count is taken from your equipped items' metadata and stays unavailable
--     while any of it is still loading.
[2894] = "遊戲中的套裝（例如層級套裝）。清單中會提供你正在穿戴的套裝；件數取自你已裝備物品的中繼資料，只要其中任何一項仍在載入，就維持為無法使用。",
-- f40f3d0c English: The number of pieces of that set you have equipped.
[2895] = "你已裝備該套裝的件數。",
-- 07cc311f English: The temporary enchant on the weapon: a poison, oil, sharpening stone or weapon
--     imbue. The current enchant ID of the selected hand is shown below the field.
[2896] = "武器上的暫時附魔：毒藥、油、磨刀石或武器灌注。所選手的目前附魔 ID 顯示在該欄位下方。",
-- de2d2147 English: item set %d
-- Context: Fallback name for an item set whose name is not known; %d is the set number.
-- %d #1: %d #1: the item set ID, e.g. 1234
[2897] = "套裝 %d",
-- a693df35 English: the number of {set} pieces you have equipped {comparison} {quantity}
[2898] = "你已裝備的{set}件數{comparison}{quantity}",
-- 84463f60 English: you {{!are|are not}} acting through %s
-- %s #1: %s #1: the action bar or context, e.g. "Main action bar"
[2899] = "你{{!正在|沒有}}透過%s進行操作",
-- c16cbdbc English: your %s weapon {{!has|does not have}} temporary enchant %s
-- %s #1: %s #1: which weapon, "main hand" or "off hand", e.g. "main hand"
-- %s #2: %s #2: the temporary enchant ID, e.g. "5400"
[2900] = "你的%s武器{{!有|沒有}}暫時附魔%s",
-- 9e163ca5 English: the time remaining on your %s weapon buff
-- %s #1: %s #1: which weapon, "main hand" or "off hand", e.g. "main hand"
[2901] = "你的%s武器增益的剩餘時間",
-- 6153a726 English: the number of stacks of your %s weapon buff
-- %s #1: %s #1: which weapon, "main hand" or "off hand", e.g. "main hand"
[2902] = "你的%s武器增益的層數",
-- 4320f428 English: Your %s weapon %s
-- Context: Sentence in weapon speed summaries: first %s is the weapon (main hand, off hand,
--     ranged), second %s is the comparison, e.g. 'Your main hand weapon attack speed is at least 2
--     seconds'.
-- %s #1: %s #1: which weapon, "ranged", "off hand" or "main hand", e.g. "main hand"
-- %s #2: %s #2: a comparison on the attack speed or swing time, e.g. "attack speed is less than 2 seconds"
[2903] = "你的%s武器%s",
-- 1f8df0f5 English: off hand
-- Context: Weapon slot in summaries: the off-hand weapon (lowercase).
[2904] = "副手",
-- c8f1b901 English: main hand
-- Context: Weapon slot in summaries: the main-hand weapon (lowercase).
[2905] = "主手",
-- c4756181 English: attack speed
-- Context: Quantity compared in the weapon speed summary: how many seconds one swing takes
--     (lowercase).
[2906] = "攻擊速度",
-- 736e26ef English: Attack Speed
-- Context: Label of the comparison in the weapon attack speed condition and its help heading.
[2907] = "攻擊速度",
-- d30240f8 English: swing time remaining
-- Context: Quantity compared in the swing timer summary: the time left until the next swing
--     (lowercase).
[2908] = "普通攻擊剩餘時間",
-- 0f6a6d02 English: Swing Time Remaining
-- Context: Label of the comparison in the swing timer condition and its help heading.
[2909] = "普通攻擊剩餘時間",
-- ec8bc0f2 English: Pet Spell History Memory (seconds)
[2910] = "寵物法術歷史保留時間（秒）",
-- c4f00344 English: Matches while your character is moving, based on current movement speed. It
--     does not test the movement of your target.
[2911] = "當你的角色正在移動時符合，依據目前移動速度判斷。它不偵測你目標的移動。",
-- be25a39b English: Matches when your pet unit exists. This does not check whether the pet is
--     alive, in range or able to use an ability.
[2912] = "當你的寵物單位存在時符合。它不檢查寵物是否存活、是否在範圍內或能否使用技能。",
-- b8867664 English: Matches when the game reports that you are outdoors. Being outdoors is
--     different from being outside an instance.
[2913] = "當遊戲回報你在戶外時符合。在戶外不同於在副本之外。",
-- 1b9a01d9 English: Matches when the game reports that you have full control of your character.
--     This does not guarantee that a particular spell is usable.
[2914] = "當遊戲回報你完全控制自己的角色時符合。這並不保證某個特定法術可用。",
-- 81668580 English: Matches while the game reports your character as stealthed. It does not test
--     whether an enemy can detect you.
[2915] = "當遊戲回報你的角色處於潛行狀態時符合。它不偵測敵人能否發現你。",
-- adce7518 English: Check whether you or your pet know this exact spell ID. An unlearned spell is a
--     valid condition that returns false, so the same rotation can adapt as you learn abilities.
--     This does not check cooldown, resources, range, or whether the spell can currently be cast.
--     Missing or restricted learned-state data stays unavailable under NOT.
[2916] = "檢查你或你的寵物是否學會了這個確切的法術 ID。未學會的法術是有效條件，結果為假，因此同一個循環可以隨著你學會技能而自動調整。它不檢查冷卻、資源、距離或該法術目前能否施放。缺少或受限的已學狀態資料在 NOT 下仍為無法使用。",
-- 521a6d1e English: Only consider auras that you applied yourself.
[2917] = "僅考慮你自己施加的光環。",
-- 678a9ea4 English: Remaining aura time is measured in seconds. Permanent auras have no expiration
--     and do not satisfy a finite refresh threshold. An absent aura does not satisfy this
--     condition. Restricted or unknown timing is unavailable, including under NOT.
[2918] = "光環剩餘時間以秒為單位。永久光環沒有到期時間，不符合有限的刷新門檻。不存在的光環不符合此條件。受限或未知的時間為無法使用，在 NOT 下同樣如此。",
-- 9d933823 English: Compare the application count of a matching aura, including charges such as
--     Earth Shield. An absent aura does not satisfy this condition; an unreadable count is
--     unavailable.
[2919] = "比較符合光環的堆疊層數，包括如大地之盾這類的充能次數。不存在的光環不符合此條件；無法讀取的層數為無法使用。",
-- d8fe1dac English: Only consider debuffs returned by the game's dispellable aura filter. This does
--     not guarantee your dispel is ready or in range.
[2920] = "僅考慮遊戲的可驅散光環過濾器傳回的減益效果。這並不保證你的驅散技能已就緒或在範圍內。",
-- f2467a92 English: With no off-hand weapon equipped, an off-hand check is false (and true under
--     NOT).
[2921] = "沒有裝備副手武器時，副手檢測為假（在 NOT 下為真）。",
-- 51ba09a6 English: Uses the native Attack range check when available. Otherwise it uses
--     LibRangeCheck's public interval to distinguish close range from beyond five yards; that
--     estimate does not prove exact melee geometry for every target. An interval spanning the
--     boundary, missing data or restricted data stays unavailable, including under NOT.
[2922] = "在可用時使用原生的「攻擊」距離檢查。否則使用 LibRangeCheck 的公開距離區間來區分近距離與五碼以外；該估算並不能保證對每個目標都精確反映近戰判定。跨越邊界的區間、缺少資料或受限資料維持為無法使用，在 NOT 下同樣如此。",
-- 2c7c2760 English: recharge time on %s
-- Context: Phrase in spell recharge summaries; %s is the spell link, e.g. 'recharge time on
--     Fireball'.
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[2923] = "%s的充能時間",
-- a407140e English: Seconds until the next spell charge. Full charges and inactive recharge timers
--     report zero. Missing, restricted, or non-charge spell data stays unavailable.
[2924] = "距離下一次法術充能的秒數。充能已滿或充能計時未執行時回報為零。缺少、受限或非充能法術的資料維持為無法使用。",
-- ab682a40 English: The elemental slot to check: Fire, Earth, Water or Air. Empty, zero-duration
--     and expired totems do not match.
[2925] = "要檢查的元素欄位：火焰、大地、水或空氣。空的、持續時間為零的與已過期的圖騰不符合。",
-- 515582f5 English: The active totem to check. Unticked, Use this exact spell rank matches its
--     localized name across ranks. Ticked, it requires the native spell ID; name-only observations
--     are unavailable.
[2926] = "要檢查的生效中圖騰。未勾選「使用這個確切的法術等級」時，依其在地化名稱比對所有等級。勾選後需要原生法術 ID；僅有名稱的觀測為無法使用。",
-- 2def9381 English: Compare the active totem's remaining seconds with this amount. An absent or
--     expired totem does not match; unavailable observations stay unavailable.
[2927] = "將生效中圖騰的剩餘秒數與此數值進行比較。不存在或已過期的圖騰不符合；無法使用的觀測維持為無法使用。",
-- f347bf5d English: This reference belongs to another talent layout. Selecting a talent explicitly
--     replaces it; viewing does not convert it.
[2928] = "此參照屬於另一種天賦配置。明確選擇一個天賦會取代它；僅檢視不會轉換它。",
-- a08e2044 English: Historical talent slot %s (unavailable)
-- %s #1: %s #1: the old talent slot number, e.g. 7
[2929] = "歷史天賦欄位 %s（無法使用）",
-- d511337a English: This client uses a different talent system. This reference is preserved but
--     cannot be evaluated.
[2930] = "此用戶端使用不同的天賦系統。此參照會被保留，但無法評估。",
-- 6491e9f8 English: Classic conditions compare points spent in a tree talent. Mists selections use
--     six tiers with three choices. Historical references from another talent system remain
--     unavailable and are never automatically converted.
[2931] = "經典版條件比較投入在天賦樹某個天賦上的點數。潘達利亞之謎的天賦選擇使用六個層級，每層三選一。來自其他天賦系統的歷史參照維持為無法使用，且永遠不會被自動轉換。",
-- e014c33d English: A form is chosen by its spell, so the condition keeps working as new forms are
--     learned and on every client language. Any rank of the form matches. The list shows the forms
--     on your stance bar, then your class's other forms on this client. A condition saved by stance
--     bar slot keeps that slot until you choose a form. If the client cannot read the active form,
--     the condition is unavailable, including under NOT.
[2932] = "形態以其法術選擇，因此隨著學會新形態，該條件仍然有效，並且在所有用戶端語言下都有效。形態的任何等級都會符合。清單先顯示姿態列上的形態，再顯示此用戶端上你職業的其他形態。以姿態列欄位儲存的條件會保留該欄位，直到你選擇一個形態。如果用戶端無法讀取目前形態，該條件無法使用，在 NOT 下同樣如此。",
-- 114a5b8b English: Stance bar slot %s (%s)
-- %s #1: %s #1: the stance bar slot number, e.g. 2
-- %s #2: %s #2: the name of the stance in that slot, e.g. "Defensive Stance"
[2933] = "姿態列欄位 %s（%s）",
-- 2eaf81a4 English: %s cast progress
-- Context: Phrase in cast progress summaries; %s is a unit, e.g. 'target's cast progress'.
-- %s #1: %s #1: the unit, in the possessive, e.g. "your target's" or "your"
[2934] = "%s 施法進度",
-- 4df1232e English: %s channel progress
-- Context: Phrase in channel progress summaries; %s is a unit, e.g. 'target's channel progress'.
-- %s #1: %s #1: the unit, in the possessive, e.g. "your target's" or "your"
[2935] = "%s 引導進度",
-- 4664827f English: Progress
-- Context: Label of the comparison in the cast/channel progress conditions: percent completed. Also
--     a help heading.
[2936] = "進度",
-- 8b7f75d4 English: How much of the current cast of {unit} is done, from 0% when it starts to 100%
--     when it completes. It follows haste and pushback, because it is measured against the cast's
--     own start and end. If the unit is not casting, this condition is not successful, whatever the
--     operator; if the cast's times cannot be read, it is unavailable, including under NOT.
[2937] = "{unit} 目前施法完成了多少，從開始時的 0% 到完成時的 100%。它會隨加速和施法推遲變化，因為它是相對於該次施法本身的開始和結束來衡量的。如果該單位沒有在施法，則無論使用什麼運算子，此條件都不成立；如果無法讀取施法時間，則無法使用，在 NOT 下同樣如此。",
-- 0a64e269 English: How much of the current channel of {unit} is done, from 0% when it starts to
--     100% when it ends. Ticks are evenly spaced through a channel, so tick N of a K-tick channel
--     lands at N/K whatever your haste: to clip Mind Flay (3 ticks) after its second tick, use at
--     least 66%. Pushback shortens a channel and the progress follows it. If the unit is not
--     channeling, this condition is not successful, whatever the operator; if the channel's times
--     cannot be read, it is unavailable, including under NOT.
[2938] = "{unit} 目前引導完成了多少，從開始時的 0% 到結束時的 100%。跳數在引導過程中均勻分布，因此 K 跳引導的第 N 跳無論加速如何都落在 N/K：要在第二跳之後打斷精神鞭笞（3 跳），請使用至少 66%。施法推遲會縮短引導，進度隨之變化。如果該單位沒有在引導，則無論使用什麼運算子，此條件都不成立；如果無法讀取引導時間，則無法使用，在 NOT 下同樣如此。",
-- 51b0dd92 English: Talent tree %s
-- Context: Fallback name for a talent tree that has no known name; %s is its number.
-- %s #1: %s #1: the talent tree number, e.g. 2
[2939] = "天賦樹 %s",
-- d695f0be English: This client does not expose a Classic talent-tree layout. The saved tree
--     reference is preserved.
[2940] = "此用戶端未提供經典版天賦樹配置。已儲存的天賦樹參照會被保留。",
-- 87d6a3d4 English: Talent tree
-- Context: Label of the dropdown in the talent condition for choosing a Classic talent tree (e.g.
--     Arms, Fury, Protection).
[2941] = "天賦樹",
-- fd027208 English: the number of points spent in %s
-- %s #1: %s #1: the name of the talent tree, e.g. "Frost"
[2942] = "%s中投入的點數",
-- 7661e068 English: Talent tree selects the Classic tree whose spent points are compared. Public
--     points are read again on the next evaluation; missing or restricted points are unavailable,
--     including under NOT. Grids and trait trees are unsupported.
[2943] = "「天賦樹」選擇要比較已投入點數的經典版天賦樹。公開點數會在下一次評估時重新讀取；缺少或受限的點數為無法使用，在 NOT 下同樣如此。不支援網格天賦與特質樹。",
-- 41312123 English: Compare whole points spent from zero to 512. An explicit comparison with zero
--     can describe an unspent tree.
[2944] = "比較已投入的整數點數，範圍為 0 到 512。明確與零比較可用來描述未投點的天賦樹。",
-- 09a80dcb English: Talent trees are named, never numbered: the list shows each tree by name, in
--     the order the talent window shows them, for the class the rotation is for. Your own class
--     takes the names the game gives its trees; another class's rotation uses Rotation Master's own
--     list of that class's trees. The rotation saves the tree's position in that order, so it keeps
--     its meaning when you share it.
[2945] = "天賦樹以名稱顯示，而不是編號：清單依天賦視窗的順序，為該輪替所針對的職業逐一顯示各個天賦樹的名稱。你自己的職業使用遊戲給其天賦樹的名稱；其他職業的輪替則使用 Rotation Master 內建的該職業天賦樹清單。輪替儲存的是天賦樹在該順序中的位置，因此分享後含義不變。",
-- 54d69f98 English: Talent tree selects the unique Classic tree with the most positive spent
--     points. Equal maxima, no spent points, missing records and restricted points are unavailable,
--     including under NOT.
[2946] = "「天賦樹」選擇投入點數最多（且大於零）的唯一經典版天賦樹。最大值相同、未投入點數、記錄缺少與受限點數均為無法使用，在 NOT 下同樣如此。",
-- e3c6aca6 English: The primary tree is derived from readable points, not the saved rotation slot.
--     Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree
--     does not assign a tank or healer role. Grids and trait trees are unsupported.
[2947] = "主要天賦樹由可讀的點數推算得出，而不是已儲存的循環欄位。混合天賦配置可能需要改用天賦樹點數或單一天賦條件；主要天賦樹不會指定坦克或治療職責。不支援網格天賦與特質樹。",
-- 5f313161 English: Item sets are checked in priority order. Bag counts use the first carried
